/* GERADO por scripts/dividir-dados.js — não edite à mão.
   A fonte editável continua sendo js/data*.js. */
registrarDetalhes({"DP-001":{"cognitivo":{"motivo":"Testar se o candidato conhece o peculato-furto (art. 312, § 1º, CP), que dispensa a posse prévia do bem.","mede":"Distinção entre peculato-apropriação, peculato-desvio e peculato-furto.","pegadinhaDesc":"A expressão 'embora não tenha a posse' induz o candidato a pensar em furto comum e marcar E.","ondeErra":"Quem decorou apenas o caput do art. 312 ('de que tem a posse') marca E.","palavraCritica":"posse","tecnica":"Ao ver crime funcional + subtração sem posse, lembre do § 1º: peculato-furto.","regraMental":"Tem posse → apropria/desvia. Não tem posse, mas se vale do cargo → peculato-furto. Sem vínculo com o cargo → furto comum."},"comentario":{"resolucao":"CERTO. O art. 312, § 1º, do CP tipifica o peculato-furto: aplica-se a mesma pena 'embora não tendo a posse do dinheiro, valor ou bem, o subtrai, ou concorre para que seja subtraído, em proveito próprio ou alheio, valendo-se de facilidade que lhe proporciona a qualidade de funcionário'.","fundamento":"CP, art. 312, caput e § 1º.","macete":"PECULATO-FURTO = 'furtou usando o crachá'. A facilidade do cargo substitui a posse.","erroComum":"Confundir com furto qualificado por abuso de confiança (art. 155, § 4º, II) — que é crime de particular.","comoBancaPensa":"A banca reproduz o § 1º quase literalmente e aposta que o candidato só estudou o caput."}},"DP-002":{"cognitivo":{"motivo":"Aferir se o candidato sabe que a corrupção passiva é crime formal.","mede":"Momento consumativo dos crimes formais contra a Administração.","pegadinhaDesc":"Cria a exigência inexistente do 'efetivo recebimento' e a blinda com 'somente'.","ondeErra":"O candidato imagina que sem dinheiro na mão não há crime consumado.","palavraCritica":"somente / efetivo recebimento","tecnica":"Crimes formais consumam-se com a conduta, não com o resultado.","regraMental":"SOLICITOU → consumou. Receber é mero exaurimento."},"comentario":{"resolucao":"ERRADO. A corrupção passiva (art. 317, CP) é crime formal: consuma-se com a simples solicitação ou aceitação da promessa de vantagem indevida, independentemente do recebimento. O recebimento posterior é exaurimento.","fundamento":"CP, art. 317; doutrina majoritária (crime formal).","macete":"Verbos 'solicitar' e 'aceitar promessa' já consumam. O mesmo raciocínio vale para a concussão ('exigir').","erroComum":"Transferir a lógica dos crimes materiais (que exigem resultado) para crimes formais.","comoBancaPensa":"Padrão clássico: pega o momento consumativo e o empurra para frente com 'somente com o efetivo...'."}},"DP-003":{"cognitivo":{"motivo":"Cobrar os vetores da insignificância fixados pelo STF (HC 84.412).","mede":"Limites jurisprudenciais do princípio da insignificância.","pegadinhaDesc":"O 'desde que o valor seja ínfimo' soa razoável e desvia a atenção da violência/grave ameaça.","ondeErra":"Foca no valor ínfimo e esquece que violência/grave ameaça afasta a atipicidade material.","palavraCritica":"violência ou grave ameaça","tecnica":"Insignificância exige ausência de periculosidade e reduzido grau de reprovabilidade — incompatíveis com violência.","regraMental":"Roubo NUNCA é insignificante (Jurisprudência pacífica: STF e STJ)."},"comentario":{"resolucao":"ERRADO. O STF exige, cumulativamente: mínima ofensividade, ausência de periculosidade social, reduzida reprovabilidade e inexpressividade da lesão. Crimes com violência ou grave ameaça (ex.: roubo) não admitem o princípio, ainda que o bem seja de valor ínfimo.","fundamento":"STF, HC 84.412/SP; jurisprudência consolidada STF/STJ sobre roubo.","jurisprudencia":"STJ: 'É inaplicável o princípio da insignificância ao crime de roubo' (entendimento pacífico).","macete":"Os 4 vetores: MARI — Mínima ofensividade, Ausência de periculosidade, Reduzida reprovabilidade, Inexpressividade da lesão.","erroComum":"Aceitar a assertiva pela parte verdadeira (valor ínfimo importa) sem julgar a parte falsa.","comoBancaPensa":"Verdade + falso emendado: mistura requisito real (valor) com hipótese vedada (violência)."}},"DP-004":{"cognitivo":{"motivo":"Confirmar o verbo nuclear da concussão (exigir) e sua natureza formal.","mede":"Consumação da concussão.","pegadinhaDesc":"O 'jamais' tenta ativar o reflexo de marcar E diante de termo absoluto — aqui ele está correto.","ondeErra":"Quem aplica cegamente a regra 'termo absoluto = errado'.","palavraCritica":"exige","tecnica":"As heurísticas de palavras são probabilísticas: sempre confirme com o conteúdo.","regraMental":"EXIGIR = concussão (formal). SOLICITAR = corrupção passiva."},"comentario":{"resolucao":"CERTO. Concussão (art. 316, CP): 'exigir, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida'. Crime formal: consuma-se com a exigência.","fundamento":"CP, art. 316.","macete":"Concussão vem de 'concutere' (sacudir): o agente 'sacode' a vítima com temor do cargo. Exigiu → consumou.","erroComum":"Confundir com corrupção passiva (solicitar) ou com extorsão (particular).","comoBancaPensa":"Usa termo absoluto VERDADEIRO para punir quem decora atalhos sem conteúdo — a banca conhece as heurísticas dos candidatos."}},"DP-005":{"cognitivo":{"motivo":"Cobrar a estrutura do art. 20 do CP com precisão terminológica.","mede":"Consequências do erro de tipo inevitável × evitável.","pegadinhaDesc":"Não há pegadinha: é literalidade correta. A banca alterna itens 'limpos' para calibrar a prova.","ondeErra":"Candidato desconfia demais e procura erro onde não existe.","palavraCritica":"inevitável / evitável","tecnica":"Checar os dois pares: inevitável→exclui dolo E culpa; evitável→exclui só o dolo.","regraMental":"Erro de TIPO mexe com o DOLO. Erro de PROIBIÇÃO mexe com a CULPABILIDADE."},"comentario":{"resolucao":"CERTO. Art. 20, CP: o erro sobre elemento constitutivo do tipo exclui o dolo, mas permite a punição por crime culposo, se previsto em lei. Sendo inevitável (escusável), exclui dolo e culpa — fato atípico.","fundamento":"CP, art. 20, caput.","macete":"TIPO = dolo. PROIBIÇÃO = potencial consciência da ilicitude (art. 21).","erroComum":"Trocar as consequências do erro de tipo pelas do erro de proibição (isenção/redução de pena).","comoBancaPensa":"Cerca de metade dos itens C/E é CERTA. Treine para reconhecer a literalidade correta sem inventar pegadinha."}},"DP-006":{"cognitivo":{"motivo":"Testar a incompatibilidade lógica entre tentativa e culpa.","mede":"Infrações que não admitem tentativa.","pegadinhaDesc":"A justificativa ('resultado não desejado') é verdadeira, mas prova exatamente o contrário da conclusão.","ondeErra":"Valida a premissa correta e aceita a conclusão errada.","palavraCritica":"tentativa + culposos","tecnica":"Tentar exige QUERER o resultado; na culpa, o agente não quer — logo, não há o que 'tentar'.","regraMental":"CCPHUC não admitem tentativa: Culposos, Contravenções, Preterdolosos, Habituais, Unissubsistentes, Condicionados."},"comentario":{"resolucao":"ERRADO. Em regra, crimes culposos não admitem tentativa, justamente porque a tentativa pressupõe dolo (vontade dirigida ao resultado não alcançado por circunstâncias alheias — art. 14, II, CP). A doutrina só excepciona a culpa imprópria (art. 20, § 1º, 2ª parte).","fundamento":"CP, art. 14, II; doutrina (culpa imprópria como exceção).","macete":"Tentativa = dolo frustrado. Sem dolo, sem tentativa.","erroComum":"Ignorar que a exceção (culpa imprópria) não transforma a exceção em regra.","comoBancaPensa":"Usa fundamento verdadeiro para sustentar conclusão falsa — julgue a CONCLUSÃO, não a beleza do argumento."}},"DP-007":{"cognitivo":{"motivo":"Literalidade do art. 25 do CP com uma palavra trocada.","mede":"Requisito da atualidade/iminência da agressão.","pegadinhaDesc":"Troca 'atual ou iminente' por 'futura, porém certa'.","ondeErra":"Leitura rápida: a frase inteira 'soa' como o art. 25.","palavraCritica":"futura","tecnica":"Em itens 'literais', escaneie os 4 pontos críticos: sujeito, verbo, tempo e condição.","regraMental":"Agressão FUTURA → não é legítima defesa (pode configurar inexigibilidade? Não: é fato típico e ilícito)."},"comentario":{"resolucao":"ERRADO. O art. 25 do CP exige agressão injusta ATUAL OU IMINENTE. Agressão futura, ainda que certa, não autoriza legítima defesa — o ordenamento espera que o agente busque a proteção estatal.","fundamento":"CP, art. 25.","macete":"Atual = está ocorrendo. Iminente = está prestes a ocorrer. Futura/passada = fora da legítima defesa.","erroComum":"Achar que a 'certeza' da agressão futura supre a atualidade.","comoBancaPensa":"Pega o dispositivo mais decorado do CP e troca exatamente a palavra que ninguém relê."}},"DP-008":{"cognitivo":{"motivo":"Cobrar o § 3º do art. 312, um dos dispositivos mais recorrentes da banca.","mede":"Efeitos da reparação do dano no peculato culposo.","pegadinhaDesc":"Item literal correto — a banca costuma trocar 'metade' por 'um terço' ou aplicar a regra ao peculato doloso; aqui não trocou.","ondeErra":"Confunde com arrependimento posterior (art. 16: redução de 1/3 a 2/3) ou aplica ao peculato doloso.","palavraCritica":"culposo","tecnica":"Antes de julgar, confirme: o item fala do peculato CULPOSO? Só nele há extinção da punibilidade.","regraMental":"Culposo + reparou antes do trânsito em julgado = punibilidade extinta. Doloso = mero arrependimento posterior."},"comentario":{"resolucao":"CERTO. Art. 312, § 3º, CP: 'No caso do parágrafo anterior [peculato culposo], a reparação do dano, se precede à sentença irrecorrível, extingue a punibilidade; se lhe é posterior, reduz de metade a pena imposta.'","fundamento":"CP, art. 312, § 3º.","macete":"Só o CULPOSO perdoa. No doloso, devolver o dinheiro não apaga o crime.","erroComum":"Estender o benefício ao peculato doloso — pegadinha favorita da banca nesse tema.","comoBancaPensa":"Quando não troca a palavra, cobra o item literal para premiar quem realmente leu a lei seca."}},"DP-009":{"cognitivo":{"motivo":"Literalidade do art. 4º do CP — teoria da atividade.","mede":"Tempo do crime (item 1.3 do edital).","pegadinhaDesc":"Item literal correto; a banca costuma trocar por 'momento do resultado' (teoria do resultado).","ondeErra":"Desconfia da literalidade e procura erro inexistente.","palavraCritica":"ação ou omissão","tecnica":"TEMPO = Atividade. LUGAR = Ubiquidade. Memorize o par antes de julgar.","regraMental":"LUTA: Lugar-Ubiquidade, Tempo-Atividade."},"comentario":{"resolucao":"CERTO. CP, art. 4º: 'Considera-se praticado o crime no momento da ação ou omissão, ainda que outro seja o momento do resultado' — teoria da atividade. Relevante para aferir imputabilidade e lei aplicável.","fundamento":"CP, art. 4º.","macete":"Menor que atira véspera dos 18 e vítima morre depois: continua inimputável — vale o momento da AÇÃO.","erroComum":"Confundir com o lugar do crime (ubiquidade, art. 6º).","comoBancaPensa":"Par LUTA é literalidade favorita — quando não troca, cobra o texto puro como C."}},"DP-010":{"cognitivo":{"motivo":"Inversão do par tempo/lugar — pegadinha estrutural do tema.","mede":"Lugar do crime (art. 6º, CP).","pegadinhaDesc":"Aplica ao LUGAR a teoria que vale para o TEMPO, reforçada pelo 'unicamente'.","ondeErra":"Decorou 'atividade' e aplica ao artigo errado.","palavraCritica":"atividade (deveria ser ubiquidade)","tecnica":"Lugar do crime abrange ação E resultado (ubiquidade) — essencial nos crimes a distância.","regraMental":"LUTA: Lugar-Ubiquidade, Tempo-Atividade — o item cruzou os pares."},"comentario":{"resolucao":"ERRADO. CP, art. 6º: considera-se praticado o crime tanto no lugar da ação ou omissão quanto no lugar onde se produziu ou deveria produzir-se o resultado — teoria da UBIQUIDADE (mista). A teoria da atividade rege o TEMPO do crime (art. 4º).","fundamento":"CP, arts. 4º e 6º.","macete":"Crime começa no Brasil e termina fora (ou vice-versa)? Ubiquidade garante a lei brasileira.","erroComum":"Cruzar as teorias dos arts. 4º e 6º.","comoBancaPensa":"Dois artigos vizinhos com teorias diferentes = cruzamento perfeito para C/E."}},"DP-011":{"cognitivo":{"motivo":"Retroatividade da lex mitior mesmo após o trânsito em julgado — art. 2º, parágrafo único.","mede":"Irretroatividade e suas exceções (itens 1.2 e 1.6 do edital).","pegadinhaDesc":"O 'ainda que transitada em julgado' parece exagerado — mas é o texto da lei.","ondeErra":"Acha que a coisa julgada barraria a retroação benéfica.","palavraCritica":"de qualquer modo favorecer","tecnica":"Lei mais grave NUNCA retroage; lei mais benéfica SEMPRE retroage — nem a coisa julgada a detém.","regraMental":"Benéfica atravessa até o trânsito em julgado (executor: juiz da execução — Súmula 611/STF)."},"comentario":{"resolucao":"CERTO. CP, art. 2º, parágrafo único: 'A lei posterior, que de qualquer modo favorecer o agente, aplica-se aos fatos anteriores, ainda que decididos por sentença condenatória transitada em julgado.' A aplicação cabe ao juízo da execução (Súmula 611/STF).","fundamento":"CF, art. 5º, XL; CP, art. 2º, parágrafo único; Súmula 611/STF.","macete":"In dubio pro reo também no tempo: o melhor direito alcança o passado.","erroComum":"Limitar a retroatividade benéfica aos processos em curso.","comoBancaPensa":"Cobra a parte 'chocante' do dispositivo (vencer a coisa julgada) apostando na dúvida do candidato."}},"DP-012":{"cognitivo":{"motivo":"Cruzamento entre a contagem penal (art. 10, CP) e a processual (art. 798, § 1º, CPP).","mede":"Contagem de prazo penal (item 1.5 do edital).","pegadinhaDesc":"Aplica ao prazo PENAL a regra do prazo PROCESSUAL.","ondeErra":"Usa a regra processual, mais conhecida do cotidiano forense.","palavraCritica":"inclui-se o dia do começo","tecnica":"Prazo penal (prescrição, decadência, pena): o dia do começo INCLUI-SE. Prazo processual: exclui-se.","regraMental":"Penal Pega o Primeiro dia. Processual Pula o primeiro."},"comentario":{"resolucao":"ERRADO. CP, art. 10: 'O dia do começo INCLUI-SE no cômputo do prazo. Contam-se os dias, os meses e os anos pelo calendário comum.' A exclusão do dia inicial é regra dos prazos processuais (CPP, art. 798, § 1º). Como prazos penais afetam o ius libertatis, a contagem é a mais favorável ao réu.","fundamento":"CP, art. 10; CPP, art. 798, § 1º.","macete":"Preso às 23h50? Aqueles 10 minutos contam como o 1º dia de pena.","erroComum":"Uniformizar as duas contagens.","comoBancaPensa":"Regras espelhadas em códigos diferentes = terreno clássico de troca."}},"DP-013":{"cognitivo":{"motivo":"Distinguir dolo eventual (art. 18, I, 2ª parte) de culpa consciente (art. 18, II) — divisor clássico em homicídios de trânsito.","mede":"Elemento subjetivo nos crimes contra a pessoa.","pegadinhaDesc":"Item conceitual correto; a banca costuma inverter — dizer que na culpa consciente o agente 'assume o risco'.","ondeErra":"Confunde 'prever o resultado' (comum aos dois) com 'aceitar o resultado' (só o dolo eventual).","palavraCritica":"assume o risco × acredita que não ocorrerá","tecnica":"Ambos PREVEEM. A diferença é a ATITUDE diante da previsão: aceita (dolo eventual) ou confia que evita (culpa consciente).","regraMental":"Dolo eventual: 'foda-se, aconteça o que acontecer'. Culpa consciente: 'vai dar certo, eu controlo'."},"comentario":{"resolucao":"CERTO. CP, art. 18: no dolo eventual (I) o agente assume o risco de produzir o resultado; na culpa consciente (II) prevê o resultado mas confia que não se produzirá. A previsão é comum aos dois — o que muda é a aceitação (consentimento no resultado).","fundamento":"CP, art. 18, I e II.","macete":"Fórmula de Frank: 'seja como for, dê no que der, não deixo de agir' = dolo eventual.","erroComum":"Achar que só o dolo eventual prevê o resultado — a culpa consciente também prevê.","comoBancaPensa":"Par espelhado de elementos subjetivos: a banca troca a atitude psíquica mantendo a previsão."}},"DP-014":{"cognitivo":{"motivo":"Cobrar a natureza preterdolosa do art. 129, § 3º, e a incompatibilidade com a tentativa.","mede":"Crimes qualificados pelo resultado / preterdolo.","pegadinhaDesc":"Item correto; a banca costuma afirmar que o resultado morte também é doloso, ou que admite tentativa.","ondeErra":"Confunde lesão seguida de morte (preterdolo) com homicídio (dolo na morte).","palavraCritica":"dolo na lesão + culpa na morte","tecnica":"Se a morte fosse desejada/aceita = homicídio. Se sobreveio por culpa = lesão seguida de morte.","regraMental":"Preterdolo = 'dolo no antecedente, culpa no consequente'. Sem dolo no resultado, não há o que 'tentar' nele."},"comentario":{"resolucao":"CERTO. CP, art. 129, § 3º: crime preterdoloso — dolo na lesão e culpa na morte. Como a tentativa exige dolo quanto ao resultado não alcançado, e a morte aqui é culposa, não se admite a forma tentada.","fundamento":"CP, art. 129, § 3º; art. 19 (responsabilidade pelo resultado agravador só a título de culpa, no mínimo).","macete":"Bateu para machucar e a vítima morreu sem querer = lesão seguida de morte, não homicídio.","erroComum":"Tratar o resultado morte como doloso e enquadrar em homicídio.","comoBancaPensa":"Crimes qualificados pelo resultado são terreno fértil para trocar preterdolo por dolo direto."}},"DP-015":{"cognitivo":{"motivo":"Diferenciar roubo próprio (violência ANTES/DURANTE) de roubo impróprio (violência DEPOIS da subtração) — art. 157, § 1º.","mede":"Crimes contra o patrimônio (item 3 do edital).","pegadinhaDesc":"Item literal correto; a banca costuma trocar 'logo depois' por 'antes' ou exigir grave ameaça (o impróprio só admite violência).","ondeErra":"Não percebe que o momento da violência define próprio × impróprio.","palavraCritica":"logo depois de subtraída","tecnica":"Violência ANTES para subtrair = roubo próprio. Violência DEPOIS para garantir = roubo impróprio.","regraMental":"Impróprio: começou como furto e 'virou' roubo pela violência posterior. Só admite VIOLÊNCIA (não grave ameaça)."},"comentario":{"resolucao":"CERTO. CP, art. 157, § 1º: o roubo impróprio ocorre quando o agente, logo depois de subtraída a coisa, emprega violência ou grave ameaça contra pessoa para assegurar a impunidade do crime ou a detenção da coisa. (Obs.: doutrina majoritária exige que a subtração já tenha se iniciado.)","fundamento":"CP, art. 157, caput e § 1º.","macete":"Furtou e, ao ser flagrado, agrediu para fugir com o bem = roubo impróprio.","erroComum":"Confundir o momento da violência ou achar que grave ameaça também basta no impróprio.","comoBancaPensa":"O elemento temporal (antes/depois) é o ponto exato de manipulação da assertiva."}},"DP-016":{"cognitivo":{"motivo":"Cobrar a Súmula 582 do STJ — teoria da apprehensio/amotio.","mede":"Momento consumativo dos crimes patrimoniais.","pegadinhaDesc":"Cria a exigência (superada) da 'posse mansa e pacífica' — teoria da ablatio, rejeitada pelo STJ.","ondeErra":"Aplica a antiga exigência de retirada da esfera de vigilância.","palavraCritica":"somente ... posse mansa e pacífica","tecnica":"Basta a inversão da posse, ainda que por breve tempo e mesmo sob perseguição imediata.","regraMental":"Roubo/furto: consuma com a APREENSÃO (tirou da vítima), não precisa fugir em paz com o bem."},"comentario":{"resolucao":"ERRADO. Súmula 582/STJ: consuma-se o roubo com a inversão da posse mediante violência ou grave ameaça, ainda que por breve tempo e em seguida à perseguição imediata, sendo PRESCINDÍVEL a posse mansa e pacífica ou desvigiada. Adota-se a teoria da apprehensio (amotio).","fundamento":"CP, art. 157; Súmula 582/STJ.","jurisprudencia":"STF, RE 102.490 (teoria da apprehensio) — mesma lógica aplicada ao furto.","macete":"Inverteu a posse = consumou. Não precisa 'fugir tranquilo' com o objeto.","erroComum":"Aplicar a teoria da ablatio (posse desvigiada), superada pela jurisprudência.","comoBancaPensa":"Momento consumativo + súmula = a banca insere o requisito antigo para induzir o erro."}},"DP-017":{"cognitivo":{"motivo":"Cobrar a natureza formal da extorsão (Súmula 96 STJ) e o critério que a separa do roubo.","mede":"Distinção roubo × extorsão nos crimes patrimoniais.","pegadinhaDesc":"A banca costuma dizer que a extorsão exige a efetiva obtenção da vantagem (crime material) — o oposto do correto.","ondeErra":"Trata a extorsão como material e exige o resultado patrimonial.","palavraCritica":"independentemente da obtenção","tecnica":"Extorsão: a vítima COLABORA (faz/tolera/deixa de fazer). Roubo: o agente SUBTRAI diretamente. Extorsão é formal.","regraMental":"Súmula 96 STJ: extorsão consuma sem a vantagem. Comportamento imprescindível da vítima = extorsão."},"comentario":{"resolucao":"CERTO. CP, art. 158; Súmula 96/STJ: 'O crime de extorsão consuma-se independentemente da obtenção da vantagem indevida.' É crime formal. Diferencia-se do roubo porque, na extorsão, a conduta da vítima é imprescindível (ela é constrangida a colaborar).","fundamento":"CP, art. 158; Súmula 96/STJ.","macete":"Sequestro relâmpago com a vítima sacando dinheiro no caixa = extorsão (art. 158, § 3º), não roubo.","erroComum":"Exigir a efetiva obtenção da vantagem (tratar como crime material).","comoBancaPensa":"Momento consumativo de crime formal é a pegadinha recorrente da banca."}},"DP-018":{"cognitivo":{"motivo":"Cobrar a mudança do Pacote Anticrime no art. 171, § 5º, do CP — tema de alta atualidade.","mede":"Ação penal nos crimes patrimoniais + alteração legislativa recente.","pegadinhaDesc":"A banca costuma manter 'incondicionada' (regime antigo) ou omitir as exceções.","ondeErra":"Responde com o regime anterior à Lei 13.964/2019 (era incondicionada).","palavraCritica":"condicionada à representação (regra) + exceções","tecnica":"Novidade legislativa recente = cobrança literal. Guarde as exceções (vítimas vulneráveis / Administração).","regraMental":"Estelionato hoje: em regra depende de representação. Vítima frágil ou o Estado → incondicionada."},"comentario":{"resolucao":"CERTO. CP, art. 171, § 5º (incluído pela Lei 13.964/2019): a ação penal é pública condicionada à representação, salvo se a vítima for a Administração Pública (direta ou indireta), criança/adolescente, pessoa com deficiência mental, maior de 70 anos ou incapaz.","fundamento":"CP, art. 171, § 5º (Lei 13.964/2019).","jurisprudencia":"STJ e STF discutiram a retroatividade da representação a processos já em curso (norma processual-penal híbrida).","macete":"Estelionato virou 'crime que espera a vítima reclamar' — salvo quando a vítima é vulnerável ou é o Estado.","erroComum":"Manter a ação como incondicionada (regime pré-2019).","comoBancaPensa":"Alteração do Pacote Anticrime cobrada de forma literal, geralmente como item CERTO."}},"DP-019":{"cognitivo":{"motivo":"Distinguir os três crimes contra a honra.","mede":"Crimes contra a pessoa — honra (item 2 do edital).","pegadinhaDesc":"Inverte as definições de calúnia e difamação.","ondeErra":"Troca 'fato definido como crime' (calúnia) por difamação.","palavraCritica":"fato criminoso (calúnia) × fato ofensivo (difamação)","tecnica":"Calúnia: fato CRIMINOSO falso. Difamação: fato OFENSIVO à reputação (não crime). Injúria: qualidade negativa (xingamento).","regraMental":"Calúnia = crime; Difamação = fato desonroso; Injúria = ofensa à dignidade (sem imputar fato)."},"comentario":{"resolucao":"ERRADO. As definições estão invertidas. CALÚNIA (art. 138): imputar falsamente FATO DEFINIDO COMO CRIME. DIFAMAÇÃO (art. 139): imputar fato OFENSIVO à reputação (não criminoso). INJÚRIA (art. 140): ofender a dignidade/decoro, sem imputar fato.","fundamento":"CP, arts. 138, 139 e 140.","macete":"Calúnia = 'você roubou' (fato-crime). Difamação = 'você não paga suas dívidas' (fato desonroso). Injúria = 'você é burro' (qualidade).","erroComum":"Trocar as definições de calúnia e difamação.","comoBancaPensa":"Trio conceitual espelhado é inversão clássica em crimes contra a honra."}},"DP-020":{"cognitivo":{"motivo":"Distinguir apropriação indébita (art. 168) do furto (art. 155).","mede":"Crimes contra o patrimônio (item 3 do edital).","pegadinhaDesc":"A banca costuma dizer que a apropriação indébita exige posse obtida por fraude/subtração.","ondeErra":"Não percebe que, na apropriação, a posse é lícita e anterior.","palavraCritica":"posse lícita anterior (apropriação) × subtração (furto)","tecnica":"Apropriação: recebeu de boa-fé e depois se apropriou. Furto: nunca teve a posse legítima.","regraMental":"Apropriação indébita = 'ficou com o que era pra devolver'. Furto = 'pegou o que nunca foi seu'."},"comentario":{"resolucao":"CERTO. CP, art. 168: na apropriação indébita, o agente já detém a posse/detenção LÍCITA da coisa e depois inverte o ânimo, passando a agir como dono. No furto (art. 155), a posse é obtida ilicitamente (subtração). O divisor é a licitude da posse inicial.","fundamento":"CP, arts. 155 e 168.","macete":"Pegou emprestado e não devolveu = apropriação. Levou escondido = furto.","erroComum":"Exigir subtração na apropriação indébita.","comoBancaPensa":"A origem da posse (lícita × ilícita) é o ponto de distinção manipulado."}},"DP-021":{"cognitivo":{"motivo":"Cobrar o elemento subjetivo especial da prevaricação (art. 319).","mede":"Crimes contra a Administração Pública (Dia 17 do plano).","pegadinhaDesc":"A banca costuma trocar 'interesse ou sentimento pessoal' por 'vantagem indevida' (que caracteriza corrupção).","ondeErra":"Confunde prevaricação (sentimento pessoal) com corrupção (vantagem).","palavraCritica":"satisfazer interesse ou sentimento pessoal","tecnica":"Prevaricação: motivação PESSOAL (sem vantagem econômica). Corrupção: vantagem indevida.","regraMental":"Prevaricação = 'fez por preguiça/vingança/favor pessoal', sem grana. Corrupção = tem vantagem."},"comentario":{"resolucao":"CERTO. CP, art. 319: prevaricar é retardar ou deixar de praticar, indevidamente, ato de ofício, ou praticá-lo contra disposição expressa de lei, para satisfazer interesse ou sentimento pessoal. O especial fim de agir (interesse/sentimento pessoal) é o que a distingue de outros crimes funcionais.","fundamento":"CP, art. 319.","macete":"Prevaricação: motivação pessoal, SEM vantagem econômica.","erroComum":"Confundir com corrupção passiva (que exige vantagem indevida).","comoBancaPensa":"Troca o elemento subjetivo (sentimento pessoal × vantagem) entre crimes funcionais."}},"DP-022":{"cognitivo":{"motivo":"Cobrar a corrupção ativa (art. 333) e seu sujeito ativo (particular).","mede":"Crimes contra a Administração — praticados por particular.","pegadinhaDesc":"A banca costuma trocar 'oferecer/prometer' (ativa) por 'solicitar/receber' (passiva) ou o sujeito (funcionário).","ondeErra":"Confunde corrupção ativa (particular oferece) com passiva (funcionário solicita/recebe).","palavraCritica":"particular oferece/promete","tecnica":"Ativa: PARTICULAR oferece/promete (art. 333). Passiva: FUNCIONÁRIO solicita/recebe/aceita (art. 317).","regraMental":"Ativa = quem dá (particular). Passiva = quem recebe (funcionário). Não precisa uma para a outra existir."},"comentario":{"resolucao":"CERTO. CP, art. 333: a corrupção ativa é praticada por particular que oferece ou promete vantagem indevida a funcionário público para determiná-lo a praticar, omitir ou retardar ato de ofício. É crime formal e independe da aceitação (a corrupção passiva, do art. 317, é autônoma).","fundamento":"CP, arts. 333 e 317.","macete":"Ativa = oferece (particular). Passiva = solicita/recebe (funcionário).","erroComum":"Trocar os verbos ou o sujeito ativo entre ativa e passiva.","comoBancaPensa":"Par ativa × passiva é cobrado invertendo verbo nuclear e sujeito."}},"DP-023":{"cognitivo":{"motivo":"Cobrar a teoria adotada no concurso de pessoas (art. 29).","mede":"Concurso de pessoas (Parte Geral do CP).","pegadinhaDesc":"A banca costuma dizer que o CP adotou a teoria pluralista (um crime para cada agente).","ondeErra":"Confunde monista (um crime para todos) com pluralista (crimes distintos).","palavraCritica":"mesmo delito, na medida da culpabilidade","tecnica":"Monista: um crime, todos respondem por ele (com individualização pela culpabilidade). Há exceções pluralistas pontuais.","regraMental":"Regra: teoria MONISTA (um crime para todos). Exceções pluralistas: ex.: corrupção ativa × passiva."},"comentario":{"resolucao":"CERTO. CP, art. 29: 'Quem, de qualquer modo, concorre para o crime incide nas penas a este cominadas, na medida de sua culpabilidade' — teoria monista/unitária. Todos respondem pelo mesmo crime, com individualização das penas. Há exceções pluralistas (ex.: aborto consentido — gestante e terceiro em tipos distintos).","fundamento":"CP, art. 29.","macete":"Monista = um crime para todos. Cada um responde 'na medida da culpabilidade'.","erroComum":"Afirmar que o CP adotou a teoria pluralista como regra.","comoBancaPensa":"Teoria monista × pluralista é cobrada por troca."}},"DP-024":{"cognitivo":{"motivo":"Cobrar a natureza hedionda e o momento consumativo da extorsão mediante sequestro (art. 159).","mede":"Crimes contra o patrimônio (item 3 do edital) + crimes hediondos.","pegadinhaDesc":"A banca costuma condicionar a consumação ao pagamento do resgate.","ondeErra":"Trata o crime como material dependente do resgate.","palavraCritica":"consuma com a privação da liberdade","tecnica":"Extorsão mediante sequestro é formal: consuma-se com a privação da liberdade, independentemente do resgate.","regraMental":"Sequestrou com fim de resgate = já consumou (formal e hediondo). Receber o resgate é exaurimento."},"comentario":{"resolucao":"CERTO. CP, art. 159: a extorsão mediante sequestro consuma-se com a privação da liberdade da vítima, visada a vantagem como condição ou preço do resgate — crime formal (independe do efetivo pagamento). É crime hediondo (Lei 8.072/1990, art. 1º, IV).","fundamento":"CP, art. 159; Lei 8.072/1990, art. 1º, IV.","macete":"Sequestrou pedindo resgate = consumou (não espera o pagamento). Hediondo.","erroComum":"Exigir o pagamento do resgate para a consumação.","comoBancaPensa":"Momento consumativo de crime formal é a pegadinha, agora com a hediondez."}},"DP-025":{"cognitivo":{"motivo":"Cobrar o tipo do constrangimento ilegal (art. 146 do CP).","mede":"Crimes contra a liberdade individual (CP, arts. 121-154-B; Dia 07 do plano).","pegadinhaDesc":"A banca costuma inverter para 'fazer o que a lei permite', descaracterizando o tipo.","ondeErra":"Troca a lógica: o crime é obrigar a NÃO fazer o permitido ou a FAZER o não obrigatório.","palavraCritica":"não fazer o permitido / fazer o não obrigatório","tecnica":"Constrangimento ilegal é subsidiário: só incide quando a conduta não configura crime mais grave.","regraMental":"Constrangimento ilegal = forçar alguém a agir contra a liberdade que a lei lhe garante."},"comentario":{"resolucao":"CERTO. CP, art. 146: constranger alguém, mediante violência ou grave ameaça, ou depois de reduzir-lhe a capacidade de resistência, a não fazer o que a lei permite, ou a fazer o que ela não manda. É crime subsidiário (cede a tipos mais graves, como roubo, estupro, extorsão).","fundamento":"CP, art. 146.","macete":"É o 'crime-mãe' da coação: forçar contra a liberdade. Se houver fim específico (subtrair, etc.), vira outro crime.","erroComum":"Inverter o objeto do constrangimento.","comoBancaPensa":"A estrutura 'não fazer o permitido / fazer o não obrigatório' é o ponto manipulado."}},"DP-026":{"cognitivo":{"motivo":"Cobrar a natureza da ação penal na ameaça (art. 147, parágrafo único).","mede":"Crimes contra a liberdade pessoal.","pegadinhaDesc":"A banca costuma tratar a ameaça como ação penal pública incondicionada.","ondeErra":"Ignora a exigência de representação prevista no parágrafo único.","palavraCritica":"condicionada à representação","tecnica":"Ameaça: mal INJUSTO e GRAVE + ação penal condicionada à representação.","regraMental":"Ameaça = precisa que a vítima represente. Mal deve ser injusto e grave (futuro e verossímil)."},"comentario":{"resolucao":"CERTO. CP, art. 147: ameaçar alguém de causar-lhe mal injusto e grave. O parágrafo único condiciona a ação penal à representação do ofendido. O mal prometido deve ser injusto, grave e verossímil.","fundamento":"CP, art. 147, parágrafo único.","macete":"Ameaça: mal injusto e grave + representação.","erroComum":"Considerar a ameaça de ação penal incondicionada.","comoBancaPensa":"Natureza da ação penal é ponto recorrente nos crimes contra a pessoa."}},"DP-027":{"cognitivo":{"motivo":"Cobrar a natureza permanente do art. 148 do CP e seus efeitos.","mede":"Crimes contra a liberdade individual.","pegadinhaDesc":"A banca costuma classificar o crime como instantâneo, negando a permanência.","ondeErra":"Confunde crime permanente com instantâneo de efeitos permanentes.","palavraCritica":"consumação se prolonga no tempo","tecnica":"Permanente: a consumação se protrai; cabe flagrante a qualquer tempo e a prescrição só corre do fim da permanência.","regraMental":"Sequestro/cárcere: enquanto a vítima está presa, o crime está 'consumando' (permanente)."},"comentario":{"resolucao":"CERTO. CP, art. 148: privar alguém de sua liberdade, mediante sequestro ou cárcere privado, é crime PERMANENTE — a consumação se protrai no tempo. Consequências: flagrante possível enquanto durar a privação e prescrição contada do fim da permanência.","fundamento":"CP, art. 148.","macete":"Permanente = 'enquanto durar, está consumando'. Igual ao tráfico na modalidade 'guardar'.","erroComum":"Classificar como crime instantâneo.","comoBancaPensa":"Natureza permanente do delito é cobrada pelos seus efeitos práticos (flagrante/prescrição)."}},"DP-028":{"cognitivo":{"motivo":"Cobrar os elementos da omissão de socorro (art. 135 do CP).","mede":"Crimes de periclitação da vida e da saúde.","pegadinhaDesc":"A banca costuma exigir o socorro mesmo com risco pessoal, ou negar a alternativa de pedir ajuda à autoridade.","ondeErra":"Ignora a cláusula 'sem risco pessoal' e a conduta alternativa.","palavraCritica":"possível sem risco pessoal","tecnica":"Basta pedir socorro à autoridade quando a assistência direta implicar risco pessoal.","regraMental":"Omissão de socorro: ajude OU chame ajuda. Só se exige quando NÃO há risco pessoal."},"comentario":{"resolucao":"CERTO. CP, art. 135: deixar de prestar assistência, quando possível sem risco pessoal, a criança abandonada/extraviada ou a pessoa inválida/ferida, ao desamparo ou em grave e iminente perigo; ou não pedir, nesses casos, o socorro da autoridade pública. É crime omissivo próprio.","fundamento":"CP, art. 135.","macete":"Sem risco pessoal: socorra ou chame a autoridade. A lei não exige heroísmo.","erroComum":"Exigir o socorro mesmo com risco à própria vida.","comoBancaPensa":"A cláusula 'sem risco pessoal' e a conduta alternativa são o foco."}},"DP-029":{"cognitivo":{"motivo":"Cobrar a Súmula 593 do STJ (presunção absoluta de vulnerabilidade).","mede":"Crimes contra a dignidade sexual (art. 217-A do CP).","pegadinhaDesc":"A banca costuma admitir o consentimento do menor como excludente.","ondeErra":"Trata a vulnerabilidade como relativa.","palavraCritica":"irrelevante o consentimento","tecnica":"Menor de 14 anos: vulnerabilidade ABSOLUTA. Consentimento e experiência não afastam o crime.","regraMental":"Menor de 14 = estupro de vulnerável, sempre. Não há 'namoro' que legitime (Súmula 593 STJ)."},"comentario":{"resolucao":"CERTO. Súmula 593/STJ: o crime de estupro de vulnerável (art. 217-A do CP) configura-se com conjunção carnal ou ato libidinoso com menor de 14 anos, sendo irrelevantes o consentimento da vítima, sua eventual experiência sexual anterior ou a existência de relacionamento amoroso. A presunção é absoluta.","fundamento":"CP, art. 217-A; Súmula 593/STJ.","macete":"Menor de 14 = vulnerabilidade absoluta. Consentimento não conta.","erroComum":"Aceitar o consentimento do menor como excludente.","comoBancaPensa":"Tema com súmula é cobrado contra a intuição de 'relativizar' o consentimento."}},"DP-030":{"cognitivo":{"motivo":"Cobrar o tipo do excesso de exação (art. 316, § 1º, do CP).","mede":"Crimes contra a Administração Pública (Dia 17 do plano).","pegadinhaDesc":"A banca costuma confundir excesso de exação com concussão ou corrupção.","ondeErra":"Não distingue exigir tributo indevido (exação) de exigir vantagem indevida (concussão).","palavraCritica":"tributo/contribuição indevido","tecnica":"Excesso de exação: objeto é TRIBUTO/contribuição (indevido ou cobrado de forma vexatória). Concussão: vantagem indevida em geral.","regraMental":"Exação = cobrança de tributo. Concussão = exigir vantagem. O objeto muda o crime."},"comentario":{"resolucao":"CERTO. CP, art. 316, § 1º: exigir tributo ou contribuição social que sabe ou deveria saber indevido, ou, quando devido, empregar na cobrança meio vexatório/gravoso não autorizado. Se o funcionário desvia o valor arrecadado em proveito próprio, incide a forma qualificada (§ 2º).","fundamento":"CP, art. 316, §§ 1º e 2º.","macete":"Exação = cobrança abusiva de TRIBUTO. Não confundir com concussão (vantagem indevida).","erroComum":"Confundir com concussão pela semelhança da conduta de 'exigir'.","comoBancaPensa":"O objeto (tributo × vantagem) distingue exação de concussão."}},"DP-031":{"cognitivo":{"motivo":"Distinguir resistência (art. 329) de desobediência (art. 330).","mede":"Crimes praticados por particular contra a Administração.","pegadinhaDesc":"A banca costuma retirar a 'violência ou ameaça' (confundindo com desobediência) ou tratar ato ilegal como objeto.","ondeErra":"Confunde resistência (com violência/ameaça) com desobediência (sem violência).","palavraCritica":"com violência ou ameaça / ato legal","tecnica":"Resistência: opor-se com VIOLÊNCIA/AMEAÇA a ato LEGAL. Desobediência: descumprir ordem legal, sem violência.","regraMental":"Resistência = revida com força. Desobediência = simplesmente não obedece. Ato ilegal não gera resistência."},"comentario":{"resolucao":"CERTO. CP, art. 329: opor-se à execução de ato LEGAL, mediante violência ou ameaça a funcionário competente ou a quem lhe presta auxílio. Sem violência/ameaça, a conduta pode configurar desobediência (art. 330). A oposição a ato ilegal não caracteriza o crime.","fundamento":"CP, arts. 329 e 330.","macete":"Resistência: força + ato legal. Desobediência: sem força.","erroComum":"Suprimir a violência/ameaça ou admitir resistência a ato ilegal.","comoBancaPensa":"Resistência × desobediência é cobrada pela presença de violência/ameaça."}},"DP-032":{"cognitivo":{"motivo":"Cobrar a jurisprudência consolidada sobre a validade do desacato.","mede":"Crimes contra a Administração — desacato (art. 331).","pegadinhaDesc":"Explora uma decisão isolada e superada do STJ de 2016 que chegou a afastar o crime.","ondeErra":"Toma como definitivo um entendimento que foi revisto.","palavraCritica":"descriminalizado (falso)","tecnica":"O STJ (3ª Seção) e o STF confirmaram que o desacato CONTINUA sendo crime, compatível com a CADH.","regraMental":"Desacato ainda é crime. A tese de descriminalização (CADH) não prevaleceu."},"comentario":{"resolucao":"ERRADO. Embora uma decisão da 5ª Turma do STJ (2016) tenha afastado o crime, a 3ª Seção do STJ e o STF firmaram que o desacato (art. 331 do CP) permanece TÍPICO e compatível com a Convenção Americana. Logo, não houve descriminalização.","fundamento":"CP, art. 331; STJ (3ª Seção, HC 379.269); STF (ADPF 496).","macete":"Desacato continua crime. A 'descriminalização pela CADH' foi rejeitada.","erroComum":"Tomar a decisão isolada de 2016 como entendimento vigente.","comoBancaPensa":"Explora uma virada jurisprudencial que não se consolidou."}},"DP-033":{"cognitivo":{"motivo":"Distinguir contrabando (art. 334-A) de descaminho (art. 334).","mede":"Crimes contra a Administração Pública.","pegadinhaDesc":"Inverte as definições dos dois crimes.","ondeErra":"Troca mercadoria proibida (contrabando) por sonegação de imposto (descaminho).","palavraCritica":"proibida (contrabando) × imposto (descaminho)","tecnica":"Contrabando: mercadoria PROIBIDA. Descaminho: iludir IMPOSTO de mercadoria permitida.","regraMental":"ConTRAbando = mercadoria proibida (traficar). Descaminho = 'descaminhar' o imposto (sonegar)."},"comentario":{"resolucao":"ERRADO. As definições estão trocadas. CONTRABANDO (art. 334-A): importar/exportar mercadoria PROIBIDA. DESCAMINHO (art. 334): iludir, total ou parcialmente, o pagamento de imposto devido sobre mercadoria permitida. A assertiva inverteu os conceitos.","fundamento":"CP, arts. 334 (descaminho) e 334-A (contrabando).","macete":"Contrabando = proibida. Descaminho = imposto (permitida, mas sem pagar).","erroComum":"Trocar as definições dos dois crimes.","comoBancaPensa":"Par espelhado (contrabando × descaminho) invertido."}},"DP-034":{"cognitivo":{"motivo":"Cobrar a modalidade do art. 313 do CP (peculato mediante erro de outrem).","mede":"Crimes contra a Administração — peculato.","pegadinhaDesc":"A banca costuma confundir com estelionato comum ou com peculato-apropriação.","ondeErra":"Não identifica o 'erro de outrem' como elemento definidor.","palavraCritica":"recebeu por erro de outrem","tecnica":"No art. 313, o funcionário recebe por ERRO de terceiro e se apropria. Difere do peculato do art. 312 (posse legítima anterior).","regraMental":"Peculato-estelionato: 'caiu no colo por erro' e o funcionário ficou com ele."},"comentario":{"resolucao":"CERTO. CP, art. 313: apropriar-se de dinheiro ou utilidade que, no exercício do cargo, recebeu por erro de outrem — é o peculato-estelionato (mediante erro de outrem). Diferencia-se do peculato do art. 312, em que a posse é legítima e anterior.","fundamento":"CP, art. 313.","macete":"Recebeu por erro alheio e ficou com o bem = peculato-estelionato (art. 313).","erroComum":"Confundir com estelionato comum ou peculato-apropriação.","comoBancaPensa":"O 'erro de outrem' é o elemento que a banca testa."}},"DP-035":{"cognitivo":{"motivo":"Cobrar o tipo da denunciação caluniosa (art. 339 do CP).","mede":"Crimes contra a administração da justiça.","pegadinhaDesc":"A banca costuma dispensar o 'sabe inocente' (dolo direto) ou confundir com calúnia.","ondeErra":"Confunde denunciação caluniosa (movimenta o aparato estatal) com calúnia (ofende a honra).","palavraCritica":"dá causa à investigação + sabe inocente","tecnica":"Denunciação caluniosa: provoca a máquina persecutória contra quem se sabe inocente. Calúnia: imputa crime falso (honra).","regraMental":"Denunciação caluniosa 'move o Estado'. Calúnia só 'suja a honra'."},"comentario":{"resolucao":"CERTO. CP, art. 339: dar causa à instauração de investigação policial, processo judicial, investigação administrativa, inquérito civil ou ação de improbidade, imputando a alguém crime de que o sabe inocente. Exige dolo direto ('sabe inocente') e a efetiva movimentação do aparato estatal.","fundamento":"CP, art. 339.","macete":"Denunciação caluniosa = acionar o Estado contra inocente. Difere da calúnia (só honra).","erroComum":"Dispensar o 'sabe inocente' ou confundir com calúnia.","comoBancaPensa":"O dolo direto e a movimentação estatal são os pontos cobrados."}},"DP-036":{"cognitivo":{"motivo":"Cobrar o tipo do falso testemunho (art. 342 do CP).","mede":"Crimes contra a administração da justiça.","pegadinhaDesc":"A banca costuma restringir o crime ao processo judicial ou excluir o inquérito policial.","ondeErra":"Ignora a abrangência (também inquérito e juízo arbitral).","palavraCritica":"processo judicial, administrativo, IP ou arbitral","tecnica":"Falso testemunho: crime de mão própria; retratação antes da sentença extingue a punibilidade.","regraMental":"Mentir como testemunha/perito em qualquer processo/IP = crime. Retratar-se a tempo apaga."},"comentario":{"resolucao":"CERTO. CP, art. 342: fazer afirmação falsa, negar ou calar a verdade, como testemunha, perito, contador, tradutor ou intérprete, em processo judicial, administrativo, inquérito policial ou juízo arbitral. É crime de mão própria; a retratação antes da sentença extingue a punibilidade (§ 2º).","fundamento":"CP, art. 342, §§ 1º e 2º.","macete":"Mentiu como testemunha/perito = crime. Retratou antes da sentença = extingue a punibilidade.","erroComum":"Restringir o crime apenas ao processo judicial.","comoBancaPensa":"A abrangência do tipo (IP, arbitral) é o ponto cobrado."}},"DP-037":{"cognitivo":{"motivo":"Distinguir comunicação falsa de crime (art. 340) de autoacusação falsa (art. 341).","mede":"Crimes contra a administração da justiça.","pegadinhaDesc":"Rotula como 'autoacusação falsa' a conduta que é 'comunicação falsa de crime'.","ondeErra":"Troca os dois tipos.","palavraCritica":"comunicar crime inexistente = art. 340 (não 341)","tecnica":"Art. 340 (comunicação falsa): avisa de crime que não houve. Art. 341 (autoacusação): confessa crime inexistente ou praticado por outrem.","regraMental":"Comunicação falsa = 'inventou um crime'. Autoacusação = 'assumiu um crime que não cometeu'."},"comentario":{"resolucao":"ERRADO. A conduta descrita (comunicar crime/contravenção que sabe não ter ocorrido, provocando a ação da autoridade) é COMUNICAÇÃO FALSA DE CRIME (art. 340). A AUTOACUSAÇÃO FALSA (art. 341) ocorre quando alguém se acusa, perante a autoridade, de crime inexistente ou cometido por outrem.","fundamento":"CP, arts. 340 e 341.","macete":"340: inventou o crime. 341: assumiu a culpa de crime que não é seu.","erroComum":"Trocar os dois tipos penais.","comoBancaPensa":"Par espelhado (comunicação falsa × autoacusação) invertido."}},"DP-038":{"cognitivo":{"motivo":"Cobrar a autonomia da receptação (art. 180, § 4º, do CP).","mede":"Crimes contra o patrimônio (item 3 do edital).","pegadinhaDesc":"Cria a exigência de condenação prévia do crime antecedente, que a lei dispensa.","ondeErra":"Trata a receptação como delito acessório dependente de condenação anterior.","palavraCritica":"depende de condenação prévia (falso)","tecnica":"Art. 180, § 4º: a receptação é punível ainda que desconhecido ou isento de pena o autor do crime antecedente.","regraMental":"Receptação é autônoma: pune-se mesmo sem condenar (ou identificar) quem cometeu o crime anterior."},"comentario":{"resolucao":"ERRADO. CP, art. 180, § 4º: a receptação é punível ainda que desconhecido ou isento de pena o autor do crime de que proveio a coisa. Não se exige a prévia condenação do autor do crime antecedente — o delito é autônomo.","fundamento":"CP, art. 180, § 4º.","macete":"Receptação pune-se sozinha: não espera condenar o ladrão original.","erroComum":"Exigir condenação prévia do crime antecedente.","comoBancaPensa":"Cria falsa dependência entre receptação e crime antecedente."}},"DP-039":{"cognitivo":{"motivo":"Cobrar a regra de punição da tentativa (art. 14, parágrafo único).","mede":"Teoria do crime — tentativa.","pegadinhaDesc":"Iguala a pena da tentativa à do consumado, ignorando a redução.","ondeErra":"Desconhece a causa de diminuição obrigatória da tentativa.","palavraCritica":"mesma pena (falso)","tecnica":"Tentativa: pena do consumado reduzida de 1/3 a 2/3 (teoria objetiva). Exceções: crimes de atentado/empreendimento.","regraMental":"Tentou mas não consumou: pena reduzida de 1/3 a 2/3. Não é a mesma do consumado."},"comentario":{"resolucao":"ERRADO. CP, art. 14, parágrafo único: salvo disposição em contrário, pune-se a tentativa com a pena do crime consumado, DIMINUÍDA de um a dois terços (teoria objetiva). Só nos crimes de atentado (empreendimento) a tentativa é punida como consumação.","fundamento":"CP, art. 14, II e parágrafo único.","macete":"Tentativa = pena do consumado − (1/3 a 2/3). Quanto mais perto de consumar, menor a redução.","erroComum":"Igualar a pena da tentativa à do consumado.","comoBancaPensa":"Omite a causa de diminuição obrigatória da tentativa."}},"DP-040":{"cognitivo":{"motivo":"Cobrar a inexistência de roubo culposo.","mede":"Crimes contra o patrimônio (item 3 do edital).","pegadinhaDesc":"Inventa a modalidade culposa do roubo.","ondeErra":"Ignora que roubo exige dolo (e emprego de violência/grave ameaça).","palavraCritica":"forma culposa (inexistente)","tecnica":"Crimes patrimoniais como furto e roubo são dolosos. Não há 'subtrair por imprudência'.","regraMental":"Não existe roubo culposo. A regra é o dolo (art. 18, parágrafo único, do CP)."},"comentario":{"resolucao":"ERRADO. O roubo (art. 157) é crime exclusivamente doloso — não existe modalidade culposa. Aliás, o CP (art. 18, parágrafo único) só admite punição por culpa quando expressamente prevista, o que não ocorre no roubo.","fundamento":"CP, arts. 18, parágrafo único, e 157.","macete":"Roubo culposo não existe. Subtrair 'sem querer' com violência é uma contradição.","erroComum":"Admitir modalidade culposa em crime patrimonial.","comoBancaPensa":"Cria modalidade culposa inexistente."}},"DP-041":{"cognitivo":{"motivo":"Cobrar a tipicidade do furto de coisa comum (art. 156 do CP).","mede":"Crimes contra o patrimônio.","pegadinhaDesc":"Afirma a atipicidade, quando há tipo penal específico.","ondeErra":"Assume que a copropriedade afasta o crime.","palavraCritica":"atípica (falso)","tecnica":"Art. 156: furtar coisa comum é crime, de ação penal condicionada à representação. Exceção: coisa fungível no valor da própria quota (§ 2º).","regraMental":"Furtar a parte dos outros condôminos é crime (art. 156), não atípico."},"comentario":{"resolucao":"ERRADO. CP, art. 156: subtrair o condômino, coerdeiro ou sócio, para si ou para outrem, a quem legitimamente a detém, a coisa comum, é crime (furto de coisa comum), de ação penal condicionada à representação. Só não é punível a subtração de coisa comum fungível cujo valor não exceda a quota do agente (§ 2º).","fundamento":"CP, art. 156, §§ 1º e 2º.","macete":"Pegar a parte dos outros condôminos = crime (art. 156). Não é atípico.","erroComum":"Achar que a copropriedade torna a conduta atípica.","comoBancaPensa":"Cria falsa atipicidade com base na titularidade parcial."}},"DP-042":{"cognitivo":{"motivo":"Cobrar a vedação à analogia in malam partem (princípio da legalidade).","mede":"Princípios penais (item 1.1 do edital).","pegadinhaDesc":"Contradiz-se: invoca a legalidade para justificar exatamente o que ela proíbe.","ondeErra":"Confunde analogia in bonam partem (admitida) com in malam partem (vedada).","palavraCritica":"incriminar por analogia","tecnica":"Legalidade: não há crime sem lei anterior. Analogia para prejudicar/incriminar é proibida.","regraMental":"Analogia contra o réu: proibida. A favor do réu: admitida."},"comentario":{"resolucao":"ERRADO. O princípio da legalidade (CF, art. 5º, XXXIX; CP, art. 1º) VEDA a analogia in malam partem — não se pode criar crime ou agravar pena por analogia. Admite-se apenas a analogia in bonam partem (a favor do réu).","fundamento":"CF, art. 5º, XXXIX; CP, art. 1º.","macete":"Legalidade = só a lei cria crime. Analogia contra o réu, jamais.","erroComum":"Inverter analogia in bonam × in malam partem.","comoBancaPensa":"Usa o próprio princípio da legalidade como falso fundamento do proibido."}},"DP-043":{"cognitivo":{"motivo":"Cobrar a irretroatividade da lei penal mais gravosa.","mede":"Lei penal no tempo (itens 1.2 e 1.6 do edital).","pegadinhaDesc":"Faz a lei mais grave retroagir, contrariando a irretroatividade.","ondeErra":"Confunde a retroatividade benéfica com a maléfica.","palavraCritica":"mais grave retroage (falso)","tecnica":"A lei penal só retroage para BENEFICIAR. A mais grave é irretroativa.","regraMental":"Lei nova pior: não pega o passado. Lei nova melhor: retroage."},"comentario":{"resolucao":"ERRADO. CF, art. 5º, XL, e CP, art. 2º: a lei penal não retroagirá, salvo para beneficiar o réu. A novatio legis in pejus (mais grave) é IRRETROATIVA, mesmo antes do trânsito em julgado.","fundamento":"CF, art. 5º, XL; CP, art. 2º e parágrafo único.","macete":"Só retroage para o bem. Lei pior não alcança fato anterior.","erroComum":"Fazer a lei mais grave retroagir.","comoBancaPensa":"Inverte a regra da retroatividade (só benéfica)."}},"DP-044":{"cognitivo":{"motivo":"Cobrar a regra do art. 73 do CP (consideram-se as qualidades da vítima visada).","mede":"Teoria do crime — erro na execução.","pegadinhaDesc":"Manda considerar a vítima atingida, quando a lei considera a vítima pretendida.","ondeErra":"Inverte qual vítima define as elementares/qualidades.","palavraCritica":"vítima atingida (deveria ser a visada)","tecnica":"Aberratio ictus: consideram-se as condições da vítima PRETENDIDA (art. 73 c/c art. 20, § 3º).","regraMental":"Errou o alvo: responde como se tivesse acertado quem QUERIA acertar."},"comentario":{"resolucao":"ERRADO. CP, art. 73: no erro na execução, o agente responde como se tivesse atingido a vítima PRETENDIDA, considerando-se as condições/qualidades desta (art. 20, § 3º), e não as da vítima efetivamente atingida.","fundamento":"CP, arts. 73 e 20, § 3º.","macete":"Aberratio ictus: valem as qualidades de quem o agente QUERIA atingir.","erroComum":"Considerar a vítima realmente atingida.","comoBancaPensa":"Troca a vítima de referência (visada × atingida)."}},"DP-045":{"cognitivo":{"motivo":"Cobrar a vedação do art. 24, § 1º, do CP.","mede":"Excludentes de ilicitude — estado de necessidade.","pegadinhaDesc":"Permite o estado de necessidade a quem tinha o dever legal de enfrentar o perigo.","ondeErra":"Ignora a restrição do § 1º do art. 24.","palavraCritica":"dever legal de enfrentar (não pode alegar)","tecnica":"Quem tem o dever legal de enfrentar o perigo (bombeiro, policial, salva-vidas) NÃO pode alegar estado de necessidade para se eximir.","regraMental":"Tem o dever de encarar o perigo? Não invoca estado de necessidade para fugir dele."},"comentario":{"resolucao":"ERRADO. CP, art. 24, § 1º: não pode alegar estado de necessidade quem tinha o DEVER LEGAL de enfrentar o perigo. O bombeiro, por exemplo, não se exime de entrar no incêndio invocando a excludente.","fundamento":"CP, art. 24, § 1º.","macete":"Dever legal de enfrentar o risco = sem estado de necessidade.","erroComum":"Estender a excludente a quem tem o dever de agir.","comoBancaPensa":"Suprime a restrição do § 1º do art. 24."}},"DP-046":{"cognitivo":{"motivo":"Cobrar a impunibilidade do crime impossível (art. 17 do CP).","mede":"Teoria do crime — crime impossível.","pegadinhaDesc":"Pune o crime impossível como tentativa, quando ele não é punível.","ondeErra":"Confunde crime impossível (atípico) com tentativa (punível).","palavraCritica":"punível (falso)","tecnica":"Art. 17: por ineficácia ABSOLUTA do meio ou impropriedade ABSOLUTA do objeto, não se pune. Se a ineficácia/impropriedade for relativa, há tentativa.","regraMental":"Crime impossível (absoluto) = não pune. Relativo = tentativa."},"comentario":{"resolucao":"ERRADO. CP, art. 17: não se pune a tentativa quando, por ineficácia absoluta do meio ou por absoluta impropriedade do objeto, é impossível consumar-se o crime (teoria objetiva temperada). O crime impossível NÃO é punível.","fundamento":"CP, art. 17.","macete":"Absoluta ineficácia/impropriedade = crime impossível = impunível.","erroComum":"Punir o crime impossível como tentativa.","comoBancaPensa":"Transforma o impunível (art. 17) em punível."}},"DP-047":{"cognitivo":{"motivo":"Cobrar o conceito de reincidência (art. 63 do CP).","mede":"Teoria da pena — reincidência.","pegadinhaDesc":"Antecipa a reincidência para antes do trânsito em julgado do crime anterior.","ondeErra":"Confunde reincidência com maus antecedentes.","palavraCritica":"antes (deveria ser depois do trânsito em julgado)","tecnica":"Reincidência: novo crime DEPOIS de transitada em julgado a condenação anterior (art. 63).","regraMental":"Reincidente = cometeu o novo crime DEPOIS de já condenado definitivamente antes."},"comentario":{"resolucao":"ERRADO. CP, art. 63: a reincidência verifica-se quando o agente comete novo crime DEPOIS de transitar em julgado a sentença que o condenou por crime anterior. Se o novo crime é anterior ao trânsito em julgado, há, no máximo, maus antecedentes.","fundamento":"CP, art. 63; Lei de Contravenções, art. 7º.","macete":"Reincidência exige condenação anterior DEFINITIVA antes do novo crime.","erroComum":"Confundir reincidência com maus antecedentes.","comoBancaPensa":"Troca 'depois' por 'antes' do trânsito em julgado."}},"DP-048":{"cognitivo":{"motivo":"Distinguir exasperação (continuado) de cúmulo material (concurso material).","mede":"Concurso de crimes.","pegadinhaDesc":"Aplica o cúmulo material ao crime continuado, que segue a exasperação.","ondeErra":"Confunde continuado (uma pena aumentada) com concurso material (soma).","palavraCritica":"cúmulo material (deveria ser exasperação)","tecnica":"Crime continuado (art. 71): aplica-se a pena de UM só crime, aumentada de 1/6 a 2/3 (exasperação).","regraMental":"Continuado = exasperação (uma pena + aumento). Concurso material = soma."},"comentario":{"resolucao":"ERRADO. CP, art. 71: no crime continuado, aplica-se a pena de um só dos crimes (se idênticas) ou a mais grave (se diversas), AUMENTADA de 1/6 a 2/3 — sistema da exasperação. O cúmulo material (soma) é do concurso material (art. 69).","fundamento":"CP, arts. 69 e 71.","macete":"Continuado = exasperação. Material = soma. Formal = exasperação (regra).","erroComum":"Aplicar a soma (cúmulo material) ao crime continuado.","comoBancaPensa":"Troca o sistema de aplicação da pena entre concursos."}},"DP-049":{"cognitivo":{"motivo":"Cobrar que o homicídio privilegiado não é hediondo.","mede":"Crimes contra a pessoa + crimes hediondos.","pegadinhaDesc":"Atribui hediondez ao privilegiado (só o qualificado é hediondo).","ondeErra":"Confunde privilegiado (redução de pena) com qualificado (hediondo).","palavraCritica":"privilegiado = hediondo (falso)","tecnica":"Homicídio QUALIFICADO é hediondo; o PRIVILEGIADO (art. 121, § 1º) não é.","regraMental":"Privilegiado reduz a pena e não é hediondo. Qualificado é hediondo."},"comentario":{"resolucao":"ERRADO. O homicídio privilegiado (art. 121, § 1º) é causa de diminuição de pena e NÃO é hediondo. Hediondo é o homicídio qualificado (art. 121, § 2º) e o simples praticado em atividade típica de grupo de extermínio (Lei 8.072/1990).","fundamento":"CP, art. 121, §§ 1º e 2º; Lei 8.072/1990, art. 1º, I.","macete":"Privilegiado: pena menor, não hediondo. Qualificado: hediondo.","erroComum":"Tratar o privilegiado como hediondo.","comoBancaPensa":"Troca privilegiado por qualificado quanto à hediondez."}},"DP-050":{"cognitivo":{"motivo":"Cobrar o rol taxativo de crimes imprescritíveis.","mede":"Teoria da pena — prescrição.","pegadinhaDesc":"Inclui o peculato entre os imprescritíveis, ampliando o rol constitucional.","ondeErra":"Assume que crimes graves contra a Administração seriam imprescritíveis.","palavraCritica":"peculato imprescritível (falso)","tecnica":"Imprescritíveis são APENAS: racismo (art. 5º, XLII) e ação de grupos armados contra a ordem constitucional (XLIV). Todos os demais prescrevem.","regraMental":"Só 2 imprescritíveis: racismo e grupos armados. Peculato prescreve."},"comentario":{"resolucao":"ERRADO. Os únicos crimes imprescritíveis na CF são o racismo (art. 5º, XLII) e a ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado Democrático (art. 5º, XLIV). O peculato, como os demais crimes, está sujeito à prescrição.","fundamento":"CF, art. 5º, XLII e XLIV.","macete":"Imprescritíveis: só racismo e grupos armados. O resto prescreve.","erroComum":"Ampliar o rol de imprescritíveis.","comoBancaPensa":"Generaliza a imprescritibilidade para crime fora do rol."}},"DP-051":{"cognitivo":{"motivo":"Cobrar os requisitos do art. 33, § 4º, e o papel da quantidade como indício (não vedação automática).","mede":"Lei de Drogas — tráfico privilegiado.","pegadinhaDesc":"Transforma um elemento de valoração (quantidade) em causa automática de exclusão.","ondeErra":"Cria vedação legal inexistente baseada apenas no volume apreendido.","palavraCritica":"por si só / automaticamente","tecnica":"Requisitos do § 4º: primariedade, bons antecedentes, não dedicação a atividades criminosas e não integrar organização criminosa. A quantidade é indício a ser valorado, não vedação automática.","regraMental":"Quantidade é indício de dedicação ao tráfico — pode afastar o privilégio, mas exige fundamentação, não é automática."},"comentario":{"resolucao":"ERRADO. A causa de diminuição do art. 33, § 4º, da Lei 11.343/2006 exige primariedade, bons antecedentes, não dedicação a atividades criminosas e não integrar organização criminosa. A quantidade e a natureza da droga podem ser valoradas como INDÍCIO de dedicação ao tráfico, mas não constituem, por si sós, causa automática de exclusão do benefício — exige-se fundamentação concreta.","fundamento":"Lei 11.343/2006, arts. 33, § 4º, e 42; jurisprudência do STF/STJ.","macete":"Quantidade pesa, mas não elimina o privilégio sozinha: precisa demonstrar a dedicação ao crime.","erroComum":"Tratar a quantidade como impeditivo automático.","comoBancaPensa":"Termo absoluto ('por si só', 'automaticamente') sobre requisito que exige valoração."}},"DP-052":{"cognitivo":{"motivo":"Cobrar que o tráfico é crime de ação múltipla, não exigindo a venda efetiva.","mede":"Lei de Drogas — tipificação.","pegadinhaDesc":"Cria a exigência de mercancia efetiva para a configuração do tráfico.","ondeErra":"Ignora que 'guardar', 'ter em depósito' e 'transportar' já configuram o art. 33.","palavraCritica":"efetiva venda (não é exigida)","tecnica":"Art. 33 é tipo misto alternativo com 18 verbos: guardar, ter em depósito, transportar etc. — a venda é apenas um deles.","regraMental":"Não precisa vender para ser tráfico. Guardar ou ter em depósito já basta."},"comentario":{"resolucao":"ERRADO. O art. 33 da Lei 11.343/2006 é tipo de ação múltipla (misto alternativo), contemplando dezoito verbos — entre eles “guardar”, “ter em depósito” e “transportar”. Não se exige a efetiva mercancia. Ademais, as circunstâncias (quantidade, balança de precisão e material de embalagem) indicam destinação ao tráfico, conforme os critérios do art. 28, § 2º.","fundamento":"Lei 11.343/2006, arts. 33 e 28, § 2º.","macete":"Balança + porções + embalagem = destinação ao tráfico, mesmo sem flagrar a venda.","erroComum":"Exigir a venda efetiva para caracterizar o tráfico.","comoBancaPensa":"Cria requisito inexistente (mercancia) para desclassificar a conduta."}},"DP-053":{"cognitivo":{"motivo":"Cobrar a mudança de natureza jurídica do feminicídio.","mede":"Direito Penal — atualização legislativa (2024).","pegadinhaDesc":"A banca mantém o feminicídio como qualificadora (redação revogada).","ondeErra":"Estuda por material anterior à Lei 14.994/2024.","palavraCritica":"crime autônomo","tecnica":"A Lei 14.994/2024 revogou a qualificadora do art. 121, § 2º, VI, e criou o art. 121-A (feminicídio autônomo).","regraMental":"Feminicídio agora é tipo próprio (art. 121-A), não mais qualificadora."},"comentario":{"resolucao":"CERTO. A Lei 14.994/2024 promoveu alteração estrutural: revogou a qualificadora do feminicídio (art. 121, § 2º, VI) e instituiu o crime autônomo do art. 121-A do CP — 'matar mulher por razões da condição do sexo feminino'. O feminicídio permanece hediondo.","fundamento":"CP, art. 121-A; Lei 14.994/2024; Lei 8.072/1990.","macete":"Feminicídio saiu da qualificadora e virou tipo autônomo (121-A).","erroComum":"Tratar o feminicídio como qualificadora do homicídio.","comoBancaPensa":"Explora quem estudou por material desatualizado."}},"DP-054":{"cognitivo":{"motivo":"Cobrar a pena do feminicídio autônomo (art. 121-A).","mede":"Direito Penal — dosimetria do feminicídio.","pegadinhaDesc":"Mantém a pena antiga da qualificadora (12 a 30 anos).","ondeErra":"Não percebe o agravamento da pena promovido pela Lei 14.994/2024.","palavraCritica":"doze a trinta","tecnica":"Art. 121-A: reclusão de 20 a 40 anos — pena mais grave do que a antiga qualificadora (12 a 30).","regraMental":"Feminicídio autônomo: 20 a 40 anos (subiu com a Lei 14.994/24)."},"comentario":{"resolucao":"ERRADO. O art. 121-A do CP, incluído pela Lei 14.994/2024, comina ao feminicídio pena de reclusão de 20 a 40 anos — patamar superior ao da antiga qualificadora (12 a 30 anos). O item reproduz a pena revogada.","fundamento":"CP, art. 121-A; Lei 14.994/2024.","macete":"Feminicídio: 20 a 40 anos.","erroComum":"Repetir a pena da antiga qualificadora.","comoBancaPensa":"Troca numérica ancorada na redação revogada."}},"DP-055":{"cognitivo":{"motivo":"Cobrar o conceito de 'razões da condição do sexo feminino'.","mede":"Direito Penal — elementar do feminicídio.","pegadinhaDesc":"A banca pode restringir a uma só das hipóteses.","ondeErra":"Esquece o menosprezo/discriminação como hipótese autônoma.","palavraCritica":"violência doméstica OU menosprezo/discriminação","tecnica":"São duas hipóteses: (I) violência doméstica e familiar; (II) menosprezo ou discriminação à condição de mulher.","regraMental":"Razões de gênero = violência doméstica OU menosprezo/discriminação."},"comentario":{"resolucao":"CERTO. O feminicídio (art. 121-A) exige que o crime seja praticado por razões da condição do sexo feminino, assim consideradas as hipóteses de (I) violência doméstica e familiar e (II) menosprezo ou discriminação à condição de mulher.","fundamento":"CP, art. 121-A, § 1º.","macete":"Duas portas: violência doméstica ou menosprezo/discriminação.","erroComum":"Reduzir a uma única hipótese.","comoBancaPensa":"Testa o conhecimento das duas hipóteses."}},"DP-056":{"cognitivo":{"motivo":"Cobrar a delimitação do sujeito passivo do feminicídio (a mulher).","mede":"Direito Penal — sujeito passivo próprio.","pegadinhaDesc":"Generaliza a vítima para 'qualquer pessoa'.","ondeErra":"Confunde motivação de gênero com abrangência universal de vítimas.","palavraCritica":"qualquer pessoa","tecnica":"O tipo é 'matar MULHER'. O sujeito passivo é próprio — a mulher (STJ reconhece a mulher trans). Não é qualquer pessoa.","regraMental":"Feminicídio: vítima é a mulher, não 'qualquer pessoa'."},"comentario":{"resolucao":"ERRADO. O feminicídio é crime de sujeito passivo próprio: a vítima é a mulher (art. 121-A, caput). Não alcança qualquer pessoa; a motivação de gênero não amplia o polo passivo para além da mulher.","fundamento":"CP, art. 121-A.","macete":"Vítima do feminicídio = mulher.","erroComum":"Universalizar a vítima.","comoBancaPensa":"Generalização indevida do sujeito passivo."}},"DP-057":{"cognitivo":{"motivo":"Cobrar o tipo de perseguição/stalking (art. 147-A).","mede":"Direito Penal — crimes contra a liberdade individual.","pegadinhaDesc":"A banca pode omitir a reiteração ou confundir com ameaça (147).","ondeErra":"Trata a perseguição como sinônimo de ameaça.","palavraCritica":"reiteradamente","tecnica":"Art. 147-A (Lei 14.132/2021): perseguir REITERADAMENTE, ameaçando integridade física/psicológica ou perturbando liberdade/privacidade.","regraMental":"Stalking = perseguir de forma reiterada (não é ato único)."},"comentario":{"resolucao":"CERTO. O art. 147-A do CP, incluído pela Lei 14.132/2021, tipifica a perseguição (stalking): perseguir alguém reiteradamente e por qualquer meio, ameaçando-lhe a integridade física ou psicológica, restringindo-lhe a locomoção ou perturbando sua esfera de liberdade ou privacidade.","fundamento":"CP, art. 147-A; Lei 14.132/2021.","macete":"Stalking = perseguição REITERADA.","erroComum":"Confundir com o crime de ameaça (art. 147).","comoBancaPensa":"Testa a elementar da reiteração."}},"DP-058":{"cognitivo":{"motivo":"Cobrar a exigência de reiteração no crime de perseguição.","mede":"Direito Penal — natureza habitual do stalking.","pegadinhaDesc":"Suprime a reiteração, admitindo ato único.","ondeErra":"Ignora que o tipo exige conduta reiterada.","palavraCritica":"único ato isolado","tecnica":"A perseguição é crime habitual: exige reiteração de atos. Um ato isolado, conforme o caso, pode configurar ameaça (147), não stalking.","regraMental":"Stalking não é ato único: precisa de reiteração."},"comentario":{"resolucao":"ERRADO. O crime de perseguição (art. 147-A) tem natureza habitual e exige reiteração de condutas, não se configurando por um único ato isolado. A prática única e pontual pode caracterizar outro delito, como a ameaça.","fundamento":"CP, art. 147-A.","macete":"Reiterou? É stalking. Ato único não basta.","erroComum":"Admitir configuração por ato único.","comoBancaPensa":"Suprime a elementar da reiteração."}},"DP-059":{"cognitivo":{"motivo":"Cobrar o crime de violência psicológica contra a mulher (art. 147-B).","mede":"Direito Penal — crimes contra a liberdade individual.","pegadinhaDesc":"A banca pode negar a autonomia do tipo ou situá-lo apenas na Lei Maria da Penha.","ondeErra":"Confunde a forma de violência (Maria da Penha) com o crime autônomo do CP.","palavraCritica":"crime autônomo","tecnica":"Art. 147-B (Lei 14.188/2021): a violência psicológica contra a mulher é crime autônomo do CP, punido com reclusão de 6 meses a 2 anos e multa.","regraMental":"Violência psicológica contra a mulher = crime do art. 147-B do CP."},"comentario":{"resolucao":"CERTO. A Lei 14.188/2021 inseriu o art. 147-B no Código Penal, tipificando a violência psicológica contra a mulher: causar dano emocional que a prejudique e perturbe seu pleno desenvolvimento ou vise degradar/controlar suas ações, mediante ameaça, constrangimento, humilhação, manipulação, isolamento, chantagem, ridicularização, entre outros.","fundamento":"CP, art. 147-B; Lei 14.188/2021.","macete":"Dano emocional à mulher = crime autônomo (147-B).","erroComum":"Tratá-la só como forma de violência da Lei Maria da Penha.","comoBancaPensa":"Testa a autonomia do tipo penal."}},"DP-060":{"cognitivo":{"motivo":"Cobrar a teoria monista do concurso de pessoas (art. 29).","mede":"Direito Penal — concurso de pessoas.","pegadinhaDesc":"Troca a teoria monista pela pluralista.","ondeErra":"Confunde a regra (monista) com as exceções pluralistas.","palavraCritica":"pluralista","tecnica":"Art. 29: adotou-se a teoria MONISTA (unitária) — todos que concorrem respondem pelo mesmo crime, na medida de sua culpabilidade. Há exceções pluralistas pontuais (ex.: aborto consentido).","regraMental":"Regra: teoria monista (um crime para todos). Pluralista é exceção."},"comentario":{"resolucao":"ERRADO. O Código Penal adotou, como regra, a teoria MONISTA (unitária) no art. 29: todos os que concorrem para o crime respondem pelo mesmo delito, na medida de sua culpabilidade. A teoria pluralista aparece apenas em exceções específicas.","fundamento":"CP, art. 29.","macete":"Concurso de pessoas: regra monista, exceção pluralista.","erroComum":"Trocar monista por pluralista.","comoBancaPensa":"Inverte a teoria adotada."}},"DP-061":{"cognitivo":{"motivo":"Cobrar a causa de diminuição da participação de menor importância.","mede":"Direito Penal — dosimetria no concurso de pessoas.","pegadinhaDesc":"A banca troca a fração (ex.: 'um terço a dois terços').","ondeErra":"Não retém a fração correta de redução.","palavraCritica":"um sexto a um terço","tecnica":"Art. 29, § 1º: participação de menor importância → redução de 1/6 a 1/3.","regraMental":"Participação de menor importância: reduz de 1/6 a 1/3."},"comentario":{"resolucao":"CERTO. O art. 29, § 1º, do CP prevê que, se a participação for de menor importância, a pena pode ser reduzida de um sexto a um terço. A causa aplica-se ao partícipe, não ao autor ou coautor.","fundamento":"CP, art. 29, § 1º.","macete":"Menor importância: 1/6 a 1/3.","erroComum":"Alterar a fração de redução.","comoBancaPensa":"Troca numérica na causa de diminuição."}},"DP-062":{"cognitivo":{"motivo":"Cobrar o sistema de aplicação da pena no concurso formal.","mede":"Direito Penal — concurso de crimes.","pegadinhaDesc":"Usa 'sempre' e o cúmulo material para o concurso formal.","ondeErra":"Confunde concurso formal (exasperação) com material (soma).","palavraCritica":"sempre somadas","tecnica":"Art. 70: no concurso formal PRÓPRIO aplica-se a exasperação (pena mais grave aumentada de 1/6 a 1/2). A soma só ocorre no formal IMPRÓPRIO (desígnios autônomos).","regraMental":"Formal próprio = exasperação. Soma só no impróprio."},"comentario":{"resolucao":"ERRADO. No concurso formal próprio, aplica-se a exasperação: a pena mais grave (ou uma delas, se iguais) é aumentada de um sexto até metade (art. 70). A soma (cúmulo material) só incide no concurso formal impróprio, quando há desígnios autônomos. Logo, não é 'sempre' soma.","fundamento":"CP, art. 70.","macete":"Formal próprio: exaspera. Impróprio: soma.","erroComum":"Somar sempre no concurso formal.","comoBancaPensa":"Termo absoluto que ignora a exasperação."}},"DP-063":{"cognitivo":{"motivo":"Cobrar a regra do crime continuado (art. 71).","mede":"Direito Penal — concurso de crimes.","pegadinhaDesc":"A banca troca a fração de aumento do continuado.","ondeErra":"Confunde a fração do continuado (1/6 a 2/3) com a do formal (1/6 a 1/2).","palavraCritica":"um sexto a dois terços","tecnica":"Art. 71: crime continuado → pena de um só crime (se idênticas) aumentada de 1/6 a 2/3. É também exasperação, mas com fração maior que a do formal.","regraMental":"Continuado: exaspera de 1/6 a 2/3 (maior que a do formal)."},"comentario":{"resolucao":"CERTO. No crime continuado (art. 71), aplica-se a pena de um só dos crimes, se idênticas, aumentada de um sexto a dois terços. Trata-se de sistema de exasperação, com fração superior à do concurso formal próprio.","fundamento":"CP, art. 71.","macete":"Continuado: 1/6 a 2/3.","erroComum":"Usar a fração do concurso formal.","comoBancaPensa":"Confusão entre as frações de exasperação."}},"DP-064":{"cognitivo":{"motivo":"Cobrar a Súmula 231 do STJ.","mede":"Direito Penal — dosimetria (2ª fase).","pegadinhaDesc":"Permite a atenuante furar o mínimo legal.","ondeErra":"Desconhece a Súmula 231 do STJ.","palavraCritica":"aquém do mínimo","tecnica":"Súmula 231 do STJ: a incidência da atenuante NÃO pode conduzir à redução da pena abaixo do mínimo legal.","regraMental":"Atenuante não fura o piso (Súmula 231 STJ)."},"comentario":{"resolucao":"ERRADO. Conforme a Súmula 231 do STJ, a incidência de circunstância atenuante não pode conduzir a pena inferior ao mínimo legal. O ajuste na 2ª fase da dosimetria respeita os limites da pena em abstrato.","fundamento":"CP, art. 65; Súmula 231 do STJ.","jurisprudencia":"STJ, Súmula 231.","macete":"Atenuante não desce abaixo do mínimo.","erroComum":"Reduzir abaixo do mínimo por atenuante.","comoBancaPensa":"Contraria entendimento sumulado."}},"DP-065":{"cognitivo":{"motivo":"Cobrar a Súmula 444 do STJ.","mede":"Direito Penal — dosimetria (1ª fase) e presunção de inocência.","pegadinhaDesc":"A banca pode admitir inquéritos/ações em curso como maus antecedentes.","ondeErra":"Ignora a presunção de inocência aplicada à pena-base.","palavraCritica":"vedada","tecnica":"Súmula 444 do STJ: inquéritos e ações penais em curso não podem elevar a pena-base — decorrência da presunção de inocência.","regraMental":"Processo em curso não é mau antecedente (Súmula 444 STJ)."},"comentario":{"resolucao":"CERTO. A Súmula 444 do STJ veda o uso de inquéritos policiais e ações penais em curso para agravar a pena-base. Só condenações transitadas em julgado podem, conforme o caso, ser valoradas como maus antecedentes ou reincidência.","fundamento":"CP, art. 59; Súmula 444 do STJ; CF, art. 5º, LVII.","jurisprudencia":"STJ, Súmula 444.","macete":"Sem trânsito em julgado, não pesa na pena-base.","erroComum":"Valorar processos em curso como antecedentes.","comoBancaPensa":"Testa a aplicação da presunção de inocência."}},"DP-066":{"cognitivo":{"motivo":"Cobrar os quatro vetores da insignificância (STF).","mede":"Direito Penal — princípio da insignificância.","pegadinhaDesc":"Reduz a insignificância ao pequeno valor da coisa.","ondeErra":"Confunde 'pequeno valor' (privilégio) com bagatela (atipicidade).","palavraCritica":"apenas","tecnica":"STF exige quatro vetores (MARI): Mínima ofensividade, Ausência de periculosidade social, Reduzido grau de reprovabilidade e Inexpressividade da lesão jurídica. Não basta o pequeno valor.","regraMental":"Insignificância: 4 vetores (MARI), não só o valor da coisa."},"comentario":{"resolucao":"ERRADO. Segundo o STF, a insignificância pressupõe quatro vetores cumulativos (MARI): mínima ofensividade da conduta, ausência de periculosidade social da ação, reduzido grau de reprovabilidade do comportamento e inexpressividade da lesão jurídica. O simples pequeno valor da coisa não basta.","fundamento":"STF, HC 84.412 (e reiterados).","jurisprudencia":"STF, HC 84.412.","macete":"MARI: 4 requisitos, não só o valor.","erroComum":"Reduzir a bagatela ao pequeno valor.","comoBancaPensa":"Restringe indevidamente os requisitos."}},"DP-067":{"cognitivo":{"motivo":"Cobrar a natureza da ação penal nos crimes sexuais (art. 225).","mede":"Direito Penal — ação penal.","pegadinhaDesc":"A banca mantém a ação condicionada à representação (redação anterior).","ondeErra":"Estuda pela redação anterior a 2018.","palavraCritica":"incondicionada","tecnica":"Lei 13.718/2018 alterou o art. 225: os crimes contra a liberdade sexual e contra vulnerável passaram a ser de ação pública INCONDICIONADA.","regraMental":"Crime sexual (pós-2018): ação pública incondicionada."},"comentario":{"resolucao":"CERTO. A Lei 13.718/2018 deu nova redação ao art. 225 do CP: os crimes contra a liberdade sexual e os crimes sexuais contra vulnerável procedem mediante ação penal pública incondicionada, superando o regime anterior de ação condicionada à representação.","fundamento":"CP, art. 225; Lei 13.718/2018.","macete":"Crime sexual hoje: incondicionada.","erroComum":"Exigir representação (regime revogado).","comoBancaPensa":"Explora quem estudou pela redação antiga."}},"DP-068":{"cognitivo":{"motivo":"Cobrar a distinção entre calúnia e injúria.","mede":"Direito Penal — crimes contra a honra.","pegadinhaDesc":"Descreve a injúria e a rotula como calúnia.","ondeErra":"Confunde imputação de fato criminoso (calúnia) com atribuição de qualidade negativa (injúria).","palavraCritica":"qualidade negativa","tecnica":"Calúnia (art. 138): imputar falsamente FATO definido como crime. Injúria (art. 140): atribuir qualidade negativa que ofende a dignidade/decoro. A assertiva descreve injúria.","regraMental":"Calúnia = fato-crime falso. Injúria = qualidade negativa."},"comentario":{"resolucao":"ERRADO. A conduta descrita — atribuir qualidade negativa que ofende a dignidade ou o decoro — caracteriza INJÚRIA (art. 140). A calúnia (art. 138) consiste em imputar falsamente a alguém FATO definido como crime.","fundamento":"CP, arts. 138 e 140.","macete":"Calúnia: fato-crime. Injúria: qualidade/xingamento.","erroComum":"Trocar os conceitos de calúnia e injúria.","comoBancaPensa":"Troca de conceitos entre crimes contra a honra."}},"DP-069":{"cognitivo":{"motivo":"Ensinar que 'termo absoluto' pode tornar a assertiva VERDADEIRA.","mede":"Direito Penal/Constitucional — direitos absolutos.","pegadinhaDesc":"O candidato marca ERRADO por instinto ('não admite exceção' parece pegadinha).","ondeErra":"Aplica mecanicamente 'termo absoluto = errado'.","palavraCritica":"não admite exceção","tecnica":"A vedação à tortura (art. 5º, III) é das pouquíssimas garantias tratadas como absolutas — não cede nem em estado de defesa/sítio (art. 136 e 139).","regraMental":"Nem todo 'nunca/sempre' é falso. Tortura: vedação absoluta mesmo."},"comentario":{"resolucao":"CERTO. A proibição de tortura e de tratamento desumano ou degradante (art. 5º, III) é considerada absoluta e integra o núcleo intangível dos direitos fundamentais, não podendo ser afastada nem durante estado de defesa ou de sítio. Aqui, o termo absoluto está correto.","fundamento":"CF, art. 5º, III; arts. 136 e 139.","macete":"Termo absoluto às vezes é VERDADE. Não marque no automático.","erroComum":"Marcar errado só por causa de 'não admite exceção'.","comoBancaPensa":"Usa o vício do candidato de rejeitar todo termo absoluto."}},"DP-070":{"cognitivo":{"motivo":"Cobrar os polos da ação penal privada.","mede":"Processo Penal/Penal — ação penal privada.","pegadinhaDesc":"Troca querelante (autor) por querelado (réu).","ondeErra":"Confunde os polos da relação processual.","palavraCritica":"querelado","tecnica":"Querelante é o ofendido (autor), que oferece a queixa. Querelado é o réu. A queixa cabe ao QUERELANTE.","regraMental":"Querelante acusa; querelado é acusado. Queixa é do querelante."},"comentario":{"resolucao":"ERRADO. Na ação penal privada, o ofendido (ou seu representante) é o querelante e oferece a queixa-crime; o querelado é o réu. Logo, a queixa cabe ao querelante, não ao querelado.","fundamento":"CPP, arts. 30 e 44; CP, art. 100, § 2º.","macete":"Querelante = autor (oferece queixa). Querelado = réu.","erroComum":"Inverter os polos da ação privada.","comoBancaPensa":"Troca de sujeitos processuais."}},"DP-071":{"cognitivo":{"motivo":"Cobrar a exceção do foro por prerrogativa de função ao júri.","mede":"Penal/Processo Penal — competência do júri.","pegadinhaDesc":"Generaliza a competência do júri, ignorando o foro constitucional.","ondeErra":"Não distingue prerrogativa fixada na CF de prerrogativa apenas em constituição estadual.","palavraCritica":"inclusive ... prerrogativa","tecnica":"A competência do júri é a regra, mas cede ao foro por prerrogativa previsto na PRÓPRIA Constituição Federal (Súmula 721 STF / SV 45): prevalece o foro constitucional.","regraMental":"Foro por prerrogativa na CF prevalece sobre o júri."},"comentario":{"resolucao":"ERRADO. Embora o júri seja competente para os crimes dolosos contra a vida, o foro por prerrogativa de função estabelecido na própria Constituição Federal prevalece sobre a competência do júri (Súmula 721 do STF e SV 45). Só a prerrogativa prevista exclusivamente em constituição estadual cede ao júri.","fundamento":"CF, art. 5º, XXXVIII; Súmula 721 do STF; SV 45.","jurisprudencia":"STF, Súmula 721 e SV 45.","macete":"Prerrogativa na CF vence o júri; só estadual cede.","erroComum":"Mandar todos ao júri, sem exceção.","comoBancaPensa":"Generalização que ignora o foro constitucional."}},"DP-072":{"cognitivo":{"motivo":"Aplicar o feminicídio autônomo (Lei 14.994/2024) ao caso.","mede":"Direito Penal — feminicídio.","pegadinhaDesc":"A banca pode negar a hediondez ou tratar como qualificadora.","ondeErra":"Usa o regime anterior à Lei 14.994/2024.","palavraCritica":"crime autônomo ... hediondo","tecnica":"Art. 121-A do CP (Lei 14.994/2024): feminicídio é crime autônomo e hediondo. Matar mulher por razões da condição do sexo feminino, em violência doméstica, subsume-se ao tipo.","regraMental":"Feminicídio: tipo autônomo (121-A) e hediondo."},"comentario":{"resolucao":"CERTO. Matar mulher por razões da condição do sexo feminino, em contexto de violência doméstica, caracteriza o feminicídio (art. 121-A do CP, incluído pela Lei 14.994/2024), crime autônomo e hediondo.","fundamento":"CP, art. 121-A; Lei 14.994/2024; Lei 8.072/1990.","macete":"Feminicídio: autônomo (121-A) + hediondo.","erroComum":"Tratar como qualificadora ou negar hediondez.","comoBancaPensa":"Aplica a lei nova ao caso concreto."}},"DP-073":{"cognitivo":{"motivo":"Cobrar a competência do júri para o feminicídio.","mede":"Penal/Processo Penal — competência.","pegadinhaDesc":"Desloca o julgamento para o juizado de violência doméstica.","ondeErra":"Confunde as atribuições do juizado (medidas protetivas) com o julgamento do crime doloso contra a vida.","palavraCritica":"afastada a competência do júri","tecnica":"O feminicídio é crime doloso contra a vida → competência do tribunal do júri (art. 5º, XXXVIII, CF). O juizado de violência doméstica cuida de medidas protetivas e de outros delitos, não do julgamento do feminicídio.","regraMental":"Feminicídio (doloso contra a vida) = júri."},"comentario":{"resolucao":"ERRADO. O feminicídio é crime doloso contra a vida e, portanto, de competência do tribunal do júri (art. 5º, XXXVIII, da CF). O juizado de violência doméstica não julga o feminicídio; atua nas medidas protetivas e em outras infrações no âmbito doméstico.","fundamento":"CF, art. 5º, XXXVIII; Lei 11.340/2006.","macete":"Crime doloso contra a vida → júri (mesmo o feminicídio).","erroComum":"Mandar o feminicídio ao juizado de violência doméstica.","comoBancaPensa":"Troca o órgão competente."}},"DP-074":{"cognitivo":{"motivo":"Aplicar o concurso de crimes ao caso (duas vítimas, dois crimes).","mede":"Direito Penal — concurso de crimes.","pegadinhaDesc":"A banca pode absorver a lesão no feminicídio (consunção indevida).","ondeErra":"Aplica consunção onde há bens jurídicos e vítimas distintos.","palavraCritica":"crime autônomo, em concurso","tecnica":"A lesão grave no irmão atinge vítima e bem jurídico distintos — constitui crime autônomo, em concurso (formal ou material, conforme a análise) com o feminicídio contra Maria.","regraMental":"Vítimas/bens distintos = crimes autônomos em concurso."},"comentario":{"resolucao":"CERTO. A lesão corporal grave contra o irmão de Maria atinge vítima e bem jurídico diversos, configurando crime autônomo em concurso com o feminicídio. Não há consunção, pois as condutas não integram um mesmo iter contra a mesma vítima.","fundamento":"CP, arts. 69/70 e 129, § 1º.","macete":"Outra vítima, outro crime — há concurso.","erroComum":"Absorver a lesão no feminicídio.","comoBancaPensa":"Testa a consunção × concurso."}},"DP-075":{"cognitivo":{"motivo":"Cobrar a progressão nos crimes hediondos aplicada ao caso.","mede":"Direito Penal — execução penal.","pegadinhaDesc":"Repete o regime integralmente fechado (inconstitucional).","ondeErra":"Desconhece o HC 82.959/STF e os percentuais da LEP.","palavraCritica":"integralmente em regime fechado","tecnica":"O regime integralmente fechado foi declarado inconstitucional (HC 82.959). Há progressão nos crimes hediondos, observados os percentuais do art. 112 da LEP (Lei 13.964/2019).","regraMental":"Hediondo progride (por percentuais). Integral fechado caiu."},"comentario":{"resolucao":"ERRADO. Ainda que hediondo, o feminicídio admite progressão de regime. A vedação ao regime integralmente fechado foi declarada inconstitucional pelo STF (HC 82.959), aplicando-se hoje os percentuais do art. 112 da LEP.","fundamento":"Lei 8.072/1990; STF, HC 82.959; LEP, art. 112.","jurisprudencia":"STF, HC 82.959.","macete":"Hediondo progride; integral fechado é passado.","erroComum":"Negar a progressão ao hediondo.","comoBancaPensa":"Restringe direito de execução já reconhecido."}},"DP-076":{"cognitivo":{"motivo":"Treinar a leitura de negação dupla ('não é incorreto' = 'é correto').","mede":"Direito Penal — peculato-furto sob embaralhamento sintático.","pegadinhaDesc":"'Não é incorreto' confunde o candidato apressado, que inverte o julgamento.","ondeErra":"Lê 'não é incorreto' como negativa e marca E.","palavraCritica":"não é incorreto (= é correto)","tecnica":"Reescreva na forma afirmativa: 'É correto afirmar que comete peculato…'. Aí julgue o conteúdo (peculato-furto, art. 312, § 1º — dispensa a posse).","regraMental":"Duas negativas se anulam. 'Não é incorreto' = 'é correto'."},"comentario":{"resolucao":"CERTO. Reescrita na forma afirmativa, a assertiva diz que 'é correto afirmar que comete peculato…', o que é verdadeiro: trata-se do peculato-furto (art. 312, § 1º, do CP), que dispensa a posse prévia do bem. O conteúdo é correto e a construção com negação dupla não o altera.","fundamento":"CP, art. 312, § 1º.","macete":"'Não é incorreto' = 'é correto'. Só então julgue o mérito.","erroComum":"Inverter o julgamento por causa da dupla negativa.","comoBancaPensa":"Embaralha a leitura com negação dupla sobre conteúdo verdadeiro."}},"DP-077":{"cognitivo":{"motivo":"Treinar a desconfiança de número de súmula fictício.","mede":"Direito Penal — insignificância + verificação de fonte.","pegadinhaDesc":"Inventa uma súmula ('912 do STJ') e ainda distorce o conteúdo ('sempre/automática').","ondeErra":"Aceita a autoridade da 'súmula' sem checar existência nem conteúdo.","palavraCritica":"Súmula 912 do STJ (inexistente) + 'sempre/automática'","tecnica":"Duplo alerta: a súmula citada não existe E o conteúdo é falso (insignificância exige os 4 vetores do STF — não é automática). Pequeno valor ≠ insignificância.","regraMental":"Número de súmula que você 'nunca viu' + termo absoluto = desconfie."},"comentario":{"resolucao":"ERRADO. Não existe a 'Súmula 912 do STJ' com esse teor, e o conteúdo é falso: a insignificância não é automática nem decorre do simples pequeno valor — exige os quatro vetores fixados pelo STF (mínima ofensividade, ausência de periculosidade social, reduzido grau de reprovabilidade e inexpressividade da lesão). A banca reveste conteúdo falso com uma súmula inventada.","fundamento":"STF, HC 84.412 (vetores da insignificância).","jurisprudencia":"STF, HC 84.412.","macete":"Desconfie do número; confirme o conteúdo pela lógica.","erroComum":"Aceitar a 'súmula' pela aparência de autoridade.","comoBancaPensa":"Fabrica súmula para dar credibilidade a conteúdo falso."}},"DP-078":{"cognitivo":{"motivo":"Item de CONTROLE: súmula real e corretamente citada, no mesmo padrão das súmulas inventadas.","mede":"Direito Penal — verificação (não rejeição reflexa) de citação.","pegadinhaDesc":"Depois de treinar súmulas fabricadas, o candidato tende a desconfiar de qualquer número, mesmo real.","ondeErra":"Marca E só porque 'parece' mais uma armadilha de número.","palavraCritica":"Súmula 231 do STJ (real e corretamente citada)","tecnica":"A Súmula 231 do STJ existe e diz exatamente isso. O número está certo e o conteúdo também — não é armadilha.","regraMental":"Confira o número E o conteúdo. Se ambos batem, marque C — desconfiança não é regra absoluta."},"comentario":{"resolucao":"CERTO. A Súmula 231 do STJ estabelece que a incidência de circunstância atenuante não pode conduzir à redução da pena abaixo do mínimo legal. A citação é real e o conteúdo, fielmente reproduzido — reconhecer isso é tão importante quanto flagrar uma súmula inventada.","fundamento":"STJ, Súmula 231; CP, art. 65.","jurisprudencia":"STJ, Súmula 231.","macete":"Súmula 231 STJ: atenuante não fura o piso. Aqui, citação correta.","erroComum":"Rejeitar por desconfiança automática do número citado.","comoBancaPensa":"Mistura súmulas reais entre as inventadas para testar se o candidato verifica, em vez de só desconfiar."}},"DP-079":{"cognitivo":{"motivo":"Item de CONTROLE: mostra uma exigência REAL, para não treinar rejeição automática de todo 'exige-se'.","mede":"Direito Penal — apropriação indébita × furto.","pegadinhaDesc":"Depois de tantas 'exigências inventadas', o candidato pode rejeitar esta por reflexo — mas ela é verdadeira.","ondeErra":"Marca E só porque a frase tem estrutura de 'exige-se X'.","palavraCritica":"posse ou detenção lícita e prévia","tecnica":"Apropriação indébita (art. 168) pressupõe posse/detenção lícita ANTERIOR; furto (art. 155) não. É requisito real, não inventado.","regraMental":"Nem toda frase com 'exige' é armadilha — confira se a lei realmente exige aquilo."},"comentario":{"resolucao":"CERTO. O crime de apropriação indébita (art. 168 do CP) pressupõe que o agente já detenha a posse ou detenção lícita da coisa, apropriando-se dela em momento posterior — é justamente esse requisito que o distingue do furto, no qual o agente subtrai o bem sem jamais ter tido sua posse legítima.","fundamento":"CP, arts. 155 e 168.","macete":"Apropriação indébita: já tinha a posse lícita antes. Furto: nunca teve.","erroComum":"Rejeitar a exigência por desconfiança automática.","comoBancaPensa":"Insere uma exigência verdadeira para testar se o candidato verifica, em vez de só desconfiar."}},"DP-080":{"cognitivo":{"motivo":"Item de CONTROLE: exigência real do art. 25 do CP.","mede":"Direito Penal — legítima defesa.","pegadinhaDesc":"O candidato pode desconfiar de 'exige' e rejeitar sem checar.","ondeErra":"Marca E por reflexo, ignorando que a moderação é requisito literal do artigo.","palavraCritica":"uso moderado dos meios necessários","tecnica":"Art. 25: reconhece-se legítima defesa quando o agente usa moderadamente os meios necessários para repelir injusta agressão, atual ou iminente. Todos os elementos são exigências reais.","regraMental":"Legítima defesa: agressão injusta + atual/iminente + meios necessários + moderação. Tudo isso É exigido."},"comentario":{"resolucao":"CERTO. O art. 25 do CP exige, para a caracterização da legítima defesa, o uso moderado dos meios necessários para repelir injusta agressão, atual ou iminente, a direito próprio ou de outrem. Todos os requisitos citados são reais e cumulativos.","fundamento":"CP, art. 25.","macete":"Legítima defesa: meios necessários + moderação + agressão injusta atual/iminente.","erroComum":"Desconfiar da exigência de moderação por reflexo.","comoBancaPensa":"Reproduz fielmente um requisito legal para testar a verificação, não a desconfiança automática."}},"DP-081":{"cognitivo":{"motivo":"Reproduz o art. 155, caput, trocando 'reclusão' por 'detenção'.","mede":"Direito Penal — furto simples.","pegadinhaDesc":"Mantém prazo e verbo corretos; só troca o tipo de pena privativa de liberdade.","ondeErra":"Não associa furto a reclusão, confundindo com crimes de menor gravidade (detenção).","palavraCritica":"detenção","tecnica":"Art. 155, caput: pena de RECLUSÃO, de 1 a 4 anos, e multa. Furto não é punido com detenção.","regraMental":"Furto simples: reclusão (não detenção), 1 a 4 anos."},"comentario":{"resolucao":"ERRADO. O art. 155, caput, do CP comina ao furto simples pena de RECLUSÃO, de um a quatro anos, e multa — não detenção. A troca do tipo de pena privativa de liberdade torna a assertiva incorreta.","fundamento":"CP, art. 155, caput.","macete":"Furto: reclusão, 1 a 4 anos + multa.","erroComum":"Confundir reclusão com detenção mantendo o prazo correto.","comoBancaPensa":"Mantém números corretos e troca só o regime de pena — teste de atenção ao detalhe."}},"DP-082":{"cognitivo":{"motivo":"Reproduz o art. 33, caput, invertendo os regimes admitidos para a detenção.","mede":"Direito Penal — execução penal, regimes.","pegadinhaDesc":"A primeira parte (reclusão) está correta, desviando a atenção do erro na segunda.","ondeErra":"Não percebe que a detenção NUNCA começa em regime fechado.","palavraCritica":"detenção, em regime fechado ou aberto","tecnica":"Art. 33, caput: reclusão pode iniciar em fechado, semiaberto ou aberto; detenção SÓ em semiaberto ou aberto (podendo haver transferência a fechado depois, se necessário).","regraMental":"Detenção nunca COMEÇA em regime fechado — só reclusão pode."},"comentario":{"resolucao":"ERRADO. Conforme o art. 33, caput, do CP, a pena de detenção deve ser cumprida em regime SEMIABERTO ou aberto (não fechado), salvo necessidade de transferência para regime fechado no curso da execução. A assertiva erra ao listar 'fechado' como regime inicial da detenção.","fundamento":"CP, art. 33, caput.","macete":"Detenção: começa semiaberto/aberto. Reclusão: pode começar em qualquer regime.","erroComum":"Confundir os regimes iniciais admitidos para cada tipo de pena.","comoBancaPensa":"Acerta a primeira metade da frase (reclusão) para 'validar' a segunda, errada (detenção)."}},"DP-083":{"cognitivo":{"motivo":"Cobrar o entendimento consolidado de que a habitualidade delitiva, em regra, afasta o princípio da insignificância.","mede":"Direito Penal — princípio da insignificância (jurisprudência).","pegadinhaDesc":"A banca pode inverter o entendimento, afirmando que a habitualidade é insuficiente para afastar o benefício.","ondeErra":"Acha que a insignificância se aplica automaticamente sempre que o valor do bem é irrisório, ignorando o histórico do agente.","palavraCritica":"afasta a incidência","tecnica":"STJ e STF entendem, de forma consolidada, que a reiteração delitiva específica (habitualidade) afasta, em regra, a aplicação do princípio da insignificância, mesmo que o valor do bem seja irrisório — o vetor da reprovabilidade da conduta se soma à análise da lesividade mínima.","regraMental":"Réu reincidente/habitual: insignificância, em regra, NÃO se aplica, mesmo com bem de valor irrisório."},"comentario":{"resolucao":"CERTO. É entendimento consolidado do STJ e do STF que a habitualidade ou a reiteração delitiva específica, em regra, afasta a incidência do princípio da insignificância, ainda que o valor do bem seja irrisório, tendo em vista o maior grau de reprovabilidade da conduta do agente que reitera a prática delitiva.","fundamento":"STF, HC 84.412/SP (requisitos da insignificância: mínima ofensividade, ausência de periculosidade social, reduzida reprovabilidade e inexpressividade da lesão); STJ, Enunciado 2 da Jurisprudência em Teses (edição 219): 'A reiteração delitiva, a reincidência e os antecedentes, em regra, afastam a aplicação do princípio da insignificância, por ausência de reduzido grau de reprovabilidade do comportamento do agente.'","macete":"Reincidência/habitualidade específica = insignificância, em regra, não se aplica.","erroComum":"Aplicar a insignificância apenas com base no valor do bem, ignorando o histórico do agente.","comoBancaPensa":"Cobra a jurisprudência real e consolidada, corrigindo uma crença intuitiva comum entre candidatos."}},"DP-084":{"cognitivo":{"motivo":"Cobrar, na forma invertida, o entendimento consolidado sobre habitualidade e insignificância.","mede":"Direito Penal — princípio da insignificância (jurisprudência).","pegadinhaDesc":"A banca combina uma premissa verdadeira (valor irrisório) com uma conclusão falsa (insuficiência da habitualidade), técnica de 'verdade + mentira'.","ondeErra":"Foca apenas no valor irrisório do bem (premissa correta) e não percebe que a conclusão sobre a habitualidade está invertida.","palavraCritica":"insuficientes para afastar","tecnica":"Ao contrário do afirmado, a jurisprudência do STJ/STF entende que a habitualidade/reiteração delitiva específica é, em regra, SUFICIENTE para afastar a insignificância, mesmo com bem de valor irrisório — o valor do bem não é o único vetor analisado.","regraMental":"Cuidado com itens que somam uma premissa certa a uma conclusão errada — leia a frase inteira."},"comentario":{"resolucao":"ERRADO. Ao contrário do afirmado, a jurisprudência consolidada do STJ e do STF entende que a habitualidade ou a reiteração delitiva específica é, em regra, SUFICIENTE para afastar a incidência do princípio da insignificância, ainda que o valor do bem atingido seja irrisório.","fundamento":"Jurisprudência consolidada do STJ e do STF sobre o princípio da insignificância.","macete":"Habitualidade específica: em regra, AFASTA a insignificância, mesmo com bem irrisório.","erroComum":"Considerar apenas o valor do bem, ignorando o vetor da reprovabilidade da conduta reincidente.","comoBancaPensa":"Técnica clássica de somar uma premissa verdadeira a uma conclusão falsa para induzir ao erro."}},"DP-085":{"cognitivo":{"motivo":"Cobrar a transformação do feminicídio em tipo penal autônomo pela Lei 14.994/2024.","mede":"Direito Penal — crimes contra a vida (feminicídio).","pegadinhaDesc":"A banca pode afirmar que o feminicídio permanece apenas qualificadora do homicídio, ignorando a alteração legislativa recente.","ondeErra":"Não atualiza o conhecimento sobre a Lei 14.994/2024, mantendo a compreensão anterior (feminicídio como qualificadora).","palavraCritica":"crime autônomo","tecnica":"A Lei nº 14.994/2024 revogou a qualificadora do feminicídio no art. 121, §2º, VI, do CP e criou o art. 121-A, tipificando o feminicídio como crime autônomo, mantendo-se o critério de que as razões da condição do sexo feminino se presumem no contexto de violência doméstica e familiar ou de menosprezo/discriminação à mulher.","regraMental":"Pós-Lei 14.994/2024: feminicídio = crime autônomo (art. 121-A), não mais qualificadora do art. 121."},"comentario":{"resolucao":"CERTO. A Lei nº 14.994/2024 (conhecida como 'Pacote Antifeminicídio') alterou o Código Penal para transformar o feminicídio, antes qualificadora do homicídio (art. 121, §2º, VI), em crime autônomo (art. 121-A, pena de reclusão de 20 a 40 anos), mantendo a presunção das razões da condição do sexo feminino nos casos de violência doméstica e familiar ou de menosprezo/discriminação à condição de mulher — fenômeno de continuidade normativo-típica, sem abolitio criminis.","fundamento":"Código Penal, art. 121-A, com redação dada pela Lei nº 14.994/2024 ('Pacote Antifeminicídio').","macete":"Feminicídio hoje é crime autônomo (art. 121-A), não mais qualificadora.","erroComum":"Manter o entendimento anterior à Lei 14.994/2024, tratando o feminicídio apenas como qualificadora.","comoBancaPensa":"Cobra atualização legislativa recente, testando se o candidato acompanha as mudanças do Código Penal."}},"DP-086":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a transformação do feminicídio em crime autônomo.","mede":"Direito Penal — crimes contra a vida (feminicídio).","pegadinhaDesc":"A banca nega a atualização legislativa recente, mantendo a redação anterior à Lei 14.994/2024 como se ainda vigente.","ondeErra":"Desconhece a Lei 14.994/2024 e presume que o regime jurídico anterior ainda está em vigor.","palavraCritica":"permanece ... exclusivamente como qualificadora","tecnica":"A Lei nº 14.994/2024 revogou a qualificadora do art. 121, §2º, VI, e criou o art. 121-A, tipificando o feminicídio como crime autônomo — a afirmação de que 'permanece exclusivamente como qualificadora' está desatualizada e incorreta.","regraMental":"Feminicídio hoje: art. 121-A (crime autônomo), não mais qualificadora do art. 121."},"comentario":{"resolucao":"ERRADO. Desde a Lei nº 14.994/2024, o feminicídio não é mais apenas qualificadora do homicídio — foi criado o art. 121-A do Código Penal, tipificando-o como crime autônomo, com pena e regime próprios.","fundamento":"Código Penal, art. 121-A, com redação dada pela Lei nº 14.994/2024.","macete":"Feminicídio: crime autônomo desde 2024 (art. 121-A).","erroComum":"Desconhecer a alteração legislativa recente e manter o entendimento anterior.","comoBancaPensa":"Testa se o candidato está atualizado quanto às mudanças legislativas mais recentes no CP."}},"DP-087":{"cognitivo":{"motivo":"Cobrar a Súmula 610 do STF sobre a consumação do latrocínio.","mede":"Direito Penal — crimes contra o patrimônio (latrocínio).","pegadinhaDesc":"A banca pode exigir a subtração efetiva dos bens para a consumação do latrocínio.","ondeErra":"Acha que o latrocínio só se consuma quando há subtração efetiva do patrimônio, além da morte.","palavraCritica":"ainda que não logre subtrair","tecnica":"Súmula 610, STF: 'Há crime de latrocínio, quando o homicídio se consuma, ainda que não se realize o agente a subtração de bens da vítima.' A consumação do latrocínio acompanha a consumação da morte, independentemente do êxito na subtração patrimonial.","regraMental":"Latrocínio consumado = morte consumada, haja ou não subtração efetiva (Súmula 610, STF)."},"comentario":{"resolucao":"CERTO. Conforme a Súmula 610 do STF, o crime de latrocínio se consuma com a morte da vítima no contexto do roubo, independentemente de o agente lograr ou não subtrair os bens pretendidos — a consumação acompanha o resultado morte, e não o resultado patrimonial.","fundamento":"STF, Súmula 610.","macete":"Latrocínio consumado = morte consumada. Subtração pode até não ocorrer.","erroComum":"Exigir a subtração efetiva do patrimônio para reconhecer a consumação do latrocínio.","comoBancaPensa":"Cobra a literalidade de uma súmula clássica sobre crimes patrimoniais violentos."}},"DP-088":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a Súmula 610 do STF sobre a consumação do latrocínio.","mede":"Direito Penal — crimes contra o patrimônio (latrocínio).","pegadinhaDesc":"A banca cria uma exigência (subtração efetiva) que a súmula do STF expressamente dispensa.","ondeErra":"Condiciona a consumação do latrocínio a um resultado (subtração) que não é exigido pela jurisprudência.","palavraCritica":"somente ... também logra êxito","tecnica":"Pela Súmula 610 do STF, o latrocínio se consuma com a morte da vítima, INDEPENDENTEMENTE de êxito na subtração — a afirmação de que a subtração efetiva é condição para a consumação está incorreta.","regraMental":"Latrocínio: a consumação acompanha a morte, não a subtração."},"comentario":{"resolucao":"ERRADO. Conforme a Súmula 610 do STF, o latrocínio se consuma com a morte da vítima no contexto do roubo, ainda que o agente não logre subtrair os bens pretendidos — não existe a exigência de êxito patrimonial para a consumação, ao contrário do que afirma o item.","fundamento":"STF, Súmula 610.","macete":"Latrocínio consumado = morte consumada, com ou sem subtração.","erroComum":"Criar uma exigência de resultado patrimonial que a jurisprudência dominante não impõe.","comoBancaPensa":"Cria uma condição inexistente para testar se o candidato confia cegamente na lógica intuitiva, sem checar a súmula."}},"DP-089":{"cognitivo":{"motivo":"Cobrar que o pagamento do débito não é causa de extinção de punibilidade no furto mediante fraude.","mede":"Direito Penal — crimes contra o patrimônio (furto qualificado por fraude).","pegadinhaDesc":"A banca pode estender ao furto uma causa extintiva de punibilidade exclusiva de outros crimes (tributários).","ondeErra":"Generaliza a regra de extinção de punibilidade pelo pagamento (própria de crimes tributários) para o furto de energia elétrica.","palavraCritica":"não extingue a punibilidade","tecnica":"O furto de energia elétrica mediante fraude (art. 155, §3º, CP) não possui previsão legal de extinção de punibilidade pelo pagamento do débito — essa causa extintiva é exceção prevista especificamente para determinados crimes tributários (ex.: Lei 9.249/1995, art. 34), não se estendendo, por analogia, aos crimes patrimoniais comuns.","regraMental":"Extinção de punibilidade pelo pagamento: exceção específica de crimes tributários, não se estende ao furto."},"comentario":{"resolucao":"CERTO. O pagamento integral do débito relativo à energia elétrica subtraída mediante fraude não extingue a punibilidade do agente, pois essa causa extintiva não tem previsão no art. 155, §3º, do CP — trata-se de exceção específica de determinados crimes tributários, não extensível por analogia aos crimes patrimoniais comuns.","fundamento":"Código Penal, art. 155, §3º; doutrina de Direito Penal (causas de extinção da punibilidade).","macete":"Pagar o débito não apaga o crime de furto — isso só vale para hipóteses tributárias específicas previstas em lei.","erroComum":"Estender por analogia a extinção de punibilidade dos crimes tributários ao furto de energia elétrica.","comoBancaPensa":"Testa se o candidato distingue regras excepcionais específicas de regras gerais do Direito Penal."}},"DP-090":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a ausência de causa extintiva de punibilidade pelo pagamento no furto.","mede":"Direito Penal — crimes contra o patrimônio (furto qualificado por fraude).","pegadinhaDesc":"A banca estende indevidamente ao furto uma causa extintiva exclusiva de crimes tributários.","ondeErra":"Generaliza a regra excepcional dos crimes tributários para todo e qualquer crime patrimonial.","palavraCritica":"tal como ... tributários","tecnica":"O art. 155, §3º, CP (furto de energia elétrica) não contém previsão de extinção de punibilidade pelo pagamento do débito — essa é uma causa extintiva exclusiva e expressa de determinados crimes tributários, não extensível por analogia ao furto.","regraMental":"Extinção de punibilidade pelo pagamento: só nos crimes com previsão legal expressa (tributários), não no furto."},"comentario":{"resolucao":"ERRADO. Não há, no art. 155, §3º, do CP, previsão de extinção de punibilidade pelo pagamento do débito relativo à energia elétrica subtraída — essa causa extintiva é exclusiva de determinados crimes tributários, com previsão legal expressa, não se estendendo por analogia ao furto.","fundamento":"Código Penal, art. 155, §3º; doutrina de Direito Penal (causas de extinção da punibilidade).","macete":"Só há extinção de punibilidade pelo pagamento onde a lei expressamente previr — não é regra geral.","erroComum":"Generalizar uma causa extintiva excepcional (crimes tributários) para o furto comum.","comoBancaPensa":"Generaliza indevidamente uma exceção legal específica para todo o campo dos crimes patrimoniais."}},"DP-091":{"cognitivo":{"motivo":"Cobrar a distinção entre peculato doloso (apropriação) e peculato culposo quanto aos efeitos da reparação do dano.","mede":"Direito Penal — crimes contra a Administração Pública (peculato).","pegadinhaDesc":"A banca pode estender ao peculato doloso o benefício de extinção de punibilidade previsto apenas para o culposo.","ondeErra":"Confunde o regime do peculato culposo (art. 312, §2º e §3º, CP) com o do peculato doloso/apropriação (caput).","palavraCritica":"não extingue ... diferentemente ... culposo","tecnica":"Art. 312, §3º, CP: no PECULATO CULPOSO, a reparação do dano, se precede à sentença irrecorrível, extingue a punibilidade (se posterior, reduz a pena pela metade). No PECULATO DOLOSO (apropriação, caput), não há essa causa extintiva — a reparação, quando muito, atenua a pena (art. 65, III, 'b', CP) ou reduz o dano na esfera cível, mas não extingue a punibilidade penal.","regraMental":"Peculato CULPOSO: reparação antes da sentença = extingue punibilidade. Peculato DOLOSO: reparação NÃO extingue."},"comentario":{"resolucao":"CERTO. A extinção de punibilidade pela reparação do dano é exclusiva do peculato CULPOSO (art. 312, §3º, CP), quando a reparação precede a sentença irrecorrível. No peculato-apropriação (doloso, caput), a reparação integral do dano antes do recebimento da denúncia não extingue a punibilidade, podendo, no máximo, funcionar como atenuante genérica.","fundamento":"Código Penal, art. 312, caput e §3º.","macete":"Peculato culposo: reparação extingue (se antes da sentença). Peculato doloso: reparação NÃO extingue.","erroComum":"Estender ao peculato doloso o benefício de extinção de punibilidade exclusivo do peculato culposo.","comoBancaPensa":"Testa a distinção fina entre os regimes do peculato doloso e culposo quanto à reparação do dano."}},"DP-092":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a reparação do dano no peculato doloso não extingue a punibilidade.","mede":"Direito Penal — crimes contra a Administração Pública (peculato).","pegadinhaDesc":"A banca estende ao peculato doloso um benefício exclusivo do peculato culposo e de crimes tributários.","ondeErra":"Confunde a regra do peculato culposo (art. 312, §3º) com o regime do peculato doloso (caput), que não admite essa causa extintiva.","palavraCritica":"extingue a punibilidade ... peculato-apropriação","tecnica":"No peculato-apropriação (doloso, art. 312, caput, CP), a reparação do dano antes da denúncia NÃO extingue a punibilidade — essa causa extintiva é exclusiva do peculato CULPOSO (art. 312, §3º), quando a reparação precede a sentença irrecorrível.","regraMental":"Peculato doloso (apropriação): reparação não extingue punibilidade, apenas atenua a pena."},"comentario":{"resolucao":"ERRADO. No peculato-apropriação (doloso), a reparação integral do dano antes do recebimento da denúncia NÃO extingue a punibilidade — esse efeito é exclusivo do peculato CULPOSO, quando a reparação precede a sentença irrecorrível (art. 312, §3º, CP).","fundamento":"Código Penal, art. 312, caput e §3º.","macete":"Só o peculato CULPOSO admite extinção de punibilidade pela reparação — não o doloso.","erroComum":"Confundir o regime do peculato culposo com o do peculato doloso (apropriação).","comoBancaPensa":"Estende indevidamente um benefício excepcional a uma modalidade de crime que não o admite."}},"DP-093":{"cognitivo":{"motivo":"Cobrar o princípio do 'tempus regit actum' na aplicação da lei processual penal no tempo.","mede":"Direito Penal — aplicação da lei penal e processual no tempo.","pegadinhaDesc":"A banca pode estender à lei processual penal o mesmo regime de retroatividade benéfica da lei penal material.","ondeErra":"Aplica à lei processual penal a lógica da retroatividade da lei penal mais benéfica (art. 2º, CP), que não se aplica à norma puramente processual.","palavraCritica":"não se cogitando ... retroatividade","tecnica":"Art. 2º, CPP: a lei processual penal aplica-se desde logo, sem prejuízo dos atos realizados sob a vigência da lei anterior (sistema do isolamento dos atos processuais) — não se aplica a retroatividade da lei penal mais benéfica, própria da lei penal material (art. 2º, CP).","regraMental":"Lei processual: aplicação imediata, atos anteriores válidos, sem 'retroatividade benéfica' (isso é da lei penal material)."},"comentario":{"resolucao":"CERTO. A lei processual penal, ao contrário da lei penal material, aplica-se de imediato aos processos em curso (art. 2º, CPP), preservando a validade dos atos já praticados sob a lei anterior (sistema do isolamento dos atos processuais), sem que se cogite, em regra, de retroatividade da norma processual mais benéfica.","fundamento":"Código de Processo Penal, art. 2º; princípio 'tempus regit actum'.","macete":"Lei processual: aplicação imediata + atos anteriores válidos, sem retroatividade benéfica.","erroComum":"Aplicar à lei processual penal a lógica de retroatividade benéfica típica da lei penal material.","comoBancaPensa":"Cobra a distinção clássica entre a aplicação da lei penal material e da lei processual penal no tempo."}},"DP-094":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a ausência de retroatividade benéfica na lei processual penal pura.","mede":"Direito Penal — aplicação da lei penal e processual no tempo.","pegadinhaDesc":"A banca estende à lei processual penal o regime de retroatividade benéfica próprio da lei penal material.","ondeErra":"Confunde os regimes de aplicação temporal da lei penal material (retroage se benéfica) e da lei processual penal pura (aplicação imediata, sem retroatividade).","palavraCritica":"admite retroatividade em benefício do acusado","tecnica":"A lei processual penal pura aplica-se de imediato aos processos em curso (art. 2º, CPP), sem que se cogite de 'retroatividade benéfica' — esse instituto é próprio da lei penal material (art. 2º, CP). Situação distinta é a das normas processuais penais materiais (ex.: prazo de prisão), que seguem regime híbrido.","regraMental":"Lei processual penal pura: aplicação imediata, sem retroatividade — não confundir com a lei penal material."},"comentario":{"resolucao":"ERRADO. A lei processual penal pura não admite o instituto da retroatividade benéfica — ela se aplica de imediato aos processos em curso, preservando os atos já praticados (art. 2º, CPP), diferentemente da lei penal material, que retroage quando mais benéfica ao réu (art. 2º, CP).","fundamento":"Código de Processo Penal, art. 2º.","macete":"Retroatividade benéfica é instituto da lei PENAL, não da lei processual penal pura.","erroComum":"Confundir os regimes de aplicação temporal da lei penal material e da lei processual penal.","comoBancaPensa":"Testa se o candidato mistura, por analogia indevida, os dois regimes de aplicação da lei no tempo."}},"DP-095":{"cognitivo":{"motivo":"Cobrar o fenômeno da ultra-atividade da lei excepcional/temporária (art. 3º, CP).","mede":"Direito Penal — aplicação da lei penal no tempo (lei excepcional/temporária).","pegadinhaDesc":"A banca pode negar a ultra-atividade, afirmando que o fim da vigência beneficia retroativamente o agente.","ondeErra":"Aplica à lei excepcional/temporária a lógica geral da abolitio criminis, ignorando a regra especial do art. 3º, CP.","palavraCritica":"ultra-atividade","tecnica":"Art. 3º, CP: a lei excepcional ou temporária, ainda que decorrido o período de sua duração ou cessadas as circunstâncias que a determinaram, aplica-se ao fato praticado durante sua vigência — é o fenômeno da ULTRA-ATIVIDADE, exceção à regra geral de que a lei posterior mais benéfica sempre retroage.","regraMental":"Lei excepcional/temporária: sempre ultra-ativa — continua se aplicando ao fato do período, mesmo depois de cessar a vigência."},"comentario":{"resolucao":"CERTO. A lei excepcional ou temporária é ultra-ativa: mesmo após cessarem as circunstâncias que a determinaram ou decorrido o prazo de vigência, ela continua se aplicando ao fato praticado durante sua vigência, nos termos do art. 3º do Código Penal — exceção à regra geral de retroatividade da lei penal mais benéfica.","fundamento":"Código Penal, art. 3º.","macete":"Lei excepcional/temporária = sempre ultra-ativa (art. 3º, CP).","erroComum":"Achar que o fim da vigência da lei excepcional beneficia retroativamente quem praticou o fato durante ela.","comoBancaPensa":"Cobra uma das exceções clássicas à regra geral da retroatividade benéfica em Direito Penal."}},"DP-096":{"cognitivo":{"motivo":"Cobrar que a extraterritorialidade incondicionada, por definição, não se sujeita a nenhuma condição, incluindo o resultado do processo no exterior.","mede":"Direito Penal — aplicação da lei penal no espaço (extraterritorialidade).","pegadinhaDesc":"A banca cria uma contradição interna: atribui uma 'condição' àquilo que é, por definição, incondicionado.","ondeErra":"Não percebe a contradição lógica entre 'incondicionada' e a existência de uma condição para sua aplicação.","palavraCritica":"depende de ... condição que caracteriza a incondicionalidade","tecnica":"Art. 7º, I, CP: nos casos de extraterritorialidade INCONDICIONADA (como o genocídio praticado por brasileiro), a lei brasileira aplica-se SEMPRE, independentemente de o agente ter sido absolvido, condenado ou punido no estrangeiro (art. 7º, §1º, CP) — não há qualquer condição para essa aplicação, e o próprio nome do instituto ('incondicionada') já indica isso.","regraMental":"Extraterritorialidade incondicionada: aplica-se SEMPRE, mesmo com absolvição no exterior — não há condição alguma."},"comentario":{"resolucao":"ERRADO. A extraterritorialidade incondicionada, por definição, não se sujeita a NENHUMA condição — a lei brasileira aplica-se ao crime de genocídio praticado por brasileiro no exterior independentemente de ele ter sido absolvido ou punido no estrangeiro (art. 7º, I e §1º, CP). O item contém uma contradição interna ao atribuir uma 'condição' a algo definido como incondicionado.","fundamento":"Código Penal, art. 7º, I e §1º.","macete":"Incondicionada = sem NENHUMA condição, nem mesmo o resultado do processo no exterior.","erroComum":"Não perceber a contradição lógica entre a nomenclatura do instituto e a condição indevidamente atribuída a ele.","comoBancaPensa":"Cria uma exigência que contradiz o próprio nome do instituto jurídico, testando a atenção do candidato ao texto."}},"DP-097":{"cognitivo":{"motivo":"Fixar o preceito secundário do homicídio qualificado.","mede":"CP, art. 121, §2º.","pegadinhaDesc":"As qualificadoras estão enumeradas com fidelidade; só o teto da pena foi reduzido.","ondeErra":"Confere as qualificadoras, encontra tudo certo e não confere a pena.","palavraCritica":"vinte e cinco anos","tecnica":"Trinta anos é o teto do homicídio qualificado — e também o antigo teto de cumprimento de pena, o que ajuda a memorizar.","regraMental":"Qualificado: 12 a 30. Simples: 6 a 20."},"comentario":{"resolucao":"ERRADO. A pena do homicídio qualificado é de reclusão, de 12 (doze) a 30 (trinta) anos. As qualificadoras descritas no enunciado estão corretas; apenas o limite máximo foi alterado.","fundamento":"CP, art. 121, §2º.","macete":"12 a 30 no qualificado; 6 a 20 no simples.","erroComum":"Reduzir o teto para 25 anos.","comoBancaPensa":"Gasta a atenção do candidato num rol longo e correto, e altera o número no fim."}},"DP-098":{"cognitivo":{"motivo":"Fixar a fração de diminuição da tentativa.","mede":"CP, art. 14, parágrafo único.","pegadinhaDesc":"A fração informada é a de outras causas de diminuição do Código, e a redação inicial é idêntica à legal.","ondeErra":"Troca a fração da tentativa pela do arrependimento posterior ou pela do aumento da tortura.","palavraCritica":"um sexto a um terço","tecnica":"A tentativa tem a fração mais generosa do Código: 1/3 a 2/3, proporcional à proximidade da consumação.","regraMental":"Tentativa: 1/3 a 2/3. Quanto mais perto de consumar, menos diminui."},"comentario":{"resolucao":"ERRADO. A tentativa é punida com a pena do crime consumado diminuída de 1 (um) a 2 (dois) terços — e não de um sexto a um terço. O quantum varia conforme a distância percorrida no iter criminis.","fundamento":"CP, art. 14, parágrafo único.","macete":"Tentativa: 1/3 a 2/3.","erroComum":"Aplicar à tentativa fração de outra causa de diminuição.","comoBancaPensa":"Mantém a redação legal integral e troca só a fração."}},"DP-099":{"cognitivo":{"motivo":"Fixar o marco temporal do arrependimento posterior.","mede":"CP, art. 16.","pegadinhaDesc":"Todos os requisitos e a fração estão corretos; apenas o marco temporal foi deslocado para frente.","ondeErra":"Confunde com a reparação do dano como atenuante genérica, que pode ocorrer até o julgamento.","palavraCritica":"até a prolação da sentença","tecnica":"O benefício premia quem repara CEDO: o corte é o recebimento da denúncia ou queixa. Depois disso, vira atenuante do art. 65, III, 'b'.","regraMental":"Antes do recebimento: redução de 1 a 2/3. Depois: só atenuante."},"comentario":{"resolucao":"ERRADO. O marco é o RECEBIMENTO da denúncia ou da queixa, não a sentença. Reparado o dano após esse momento, o fato deixa de configurar arrependimento posterior e passa a ser considerado apenas como circunstância atenuante genérica.","fundamento":"CP, art. 16; art. 65, III, 'b'.","macete":"Arrependimento posterior morre no recebimento da denúncia.","erroComum":"Estender o prazo até a sentença.","comoBancaPensa":"Acerta requisitos e fração e desloca só o marco temporal, que é o elemento menos memorizado."}},"DP-100":{"cognitivo":{"motivo":"Distinguir a majorante da arma de fogo das demais majorantes do roubo.","mede":"CP, art. 157, §2º-A, I.","pegadinhaDesc":"A fração citada é a das majorantes do §2º — correta para concurso de pessoas, mas não para arma de fogo.","ondeErra":"Aplica a fração genérica do §2º à hipótese específica do §2º-A.","palavraCritica":"de um terço até metade","tecnica":"Arma de fogo saiu do §2º e ganhou parágrafo próprio, com fração fixa e mais severa: 2/3.","regraMental":"§2º (concurso, transporte de valores...): 1/3 até metade. §2º-A (arma de fogo): 2/3."},"comentario":{"resolucao":"ERRADO. O emprego de arma de fogo majora a pena em 2/3 (dois terços), por força do art. 157, §2º-A, I. A fração de 1/3 até metade aplica-se às majorantes do §2º, como o concurso de duas ou mais pessoas.","fundamento":"CP, art. 157, §2º-A, I; art. 157, §2º.","macete":"Arma de fogo no roubo: 2/3, fração fixa.","erroComum":"Usar a fração variável do §2º para arma de fogo.","comoBancaPensa":"Troca a fração entre parágrafos vizinhos do mesmo artigo."}},"DP-101":{"cognitivo":{"motivo":"Fixar os patamares de fixação do regime inicial.","mede":"CP, art. 33, §2º.","pegadinhaDesc":"A estrutura da frase reproduz a alínea 'a' e altera apenas o patamar.","ondeErra":"Mistura o patamar do regime fechado com o limite de substituição por restritivas de direitos (4 anos) ou com outros marcos.","palavraCritica":"superior a seis anos","tecnica":"Memorize a escada por potências de dois: até 4 aberto, de 4 a 8 semiaberto, acima de 8 fechado.","regraMental":"4 e 8 são os degraus. Seis não é degrau de regime."},"comentario":{"resolucao":"ERRADO. O regime inicial fechado é obrigatório para o condenado cuja pena seja superior a 8 (oito) anos. Penas superiores a 4 e não excedentes a 8 anos comportam regime semiaberto ao não reincidente; penas iguais ou inferiores a 4 anos, regime aberto.","fundamento":"CP, art. 33, §2º, alíneas 'a', 'b' e 'c'.","macete":"Degraus do regime: 4 e 8 anos.","erroComum":"Adotar 6 anos como marco do regime fechado.","comoBancaPensa":"Insere um número intermediário plausível entre os dois degraus verdadeiros."}}});
